let lang='ja',S,db,page='home',helpMode=false,undoState=null,overlayCleanup=null,timers=[],recording=null,audioChunks=[],pendingSound=null;
const $=(id)=>document.getElementById(id), esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>(I[k]||[k,k,k])[{ja:0,en:1,fr:2}[lang]],L=(a,b,c)=>[a,b||a,c||b||a][{ja:0,en:1,fr:2}[lang]],uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2),day=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,localDT=(d=new Date())=>day(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
const stamp=s=>new Date(s).toLocaleString({ja:'ja-JP',en:'en-GB',fr:'fr-FR'}[lang]);
const defaults=()=>({schema:1,entries:[],medications:[],plans:[],contacts:Array.from({length:30},()=>({name:'',number:''})),owner:{},frames:[],fortune:{},settings:{lang:'ja',dark:false,large:false,hidden:[],ownerVisible:false},lastBackup:null});
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toast.id);toast.id=setTimeout(()=>$('toast').hidden=true,5500)}
function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('watashiplus-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('data');q.onsuccess=()=>{db=q.result;resolve()};q.onerror=()=>reject(q.error)})}
function readDB(){return new Promise((resolve,reject)=>{const q=db.transaction('data').objectStore('data').get('state');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
function writeDB(value){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(value,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('aborted'))})}
let mutationQueue=Promise.resolve();
function mutate(...args){const task=mutationQueue.then(()=>transact(...args));mutationQueue=task.catch(()=>{});return task}
async function transact(fn,{undo=true,refresh=true}={}){const next=structuredClone(S);try{fn(next);await writeDB(next);S=next;if(refresh)render();return true}catch(e){toast(t('failed'));console.error('Storage error',e.name);return false}}
async function undo(){if(!undoState)return;const previous=undoState;if(await mutate(n=>{Object.keys(n).forEach(k=>delete n[k]);Object.assign(n,previous)},{undo:false})){undoState=null;render();toast(L('取り消しました','Undone','Annulé'))}}
const btn=(label,action,cls='',help='')=>`<button type="button" class="${cls}" data-action="${esc(action)}" data-help="${esc(help||action.split(':')[0])}">${label}</button>`;
const field=(label,id,value='',type='text',attrs='')=>`<label>${esc(label)}<input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const area=(label,id,value='')=>`<label>${esc(label)}<textarea id="${id}">${esc(value)}</textarea></label>`;
const select=(label,id,arr,value='')=>`<label>${esc(label)}<select id="${id}">${arr.map(a=>{const v=Array.isArray(a)?a[0]:a,n=Array.isArray(a)?a[1]:a;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`}).join('')}</select></label>`;
const icons={diary:'📖',vitals:'📈',women:'🌷',meds:'💊',plans:'◷',quiz:'ABC',games:'♟',fortune:'☯',frame:'▣',phone:'☎',calendar:'▦',search:'⌕',trash:'♲',backup:'↗',settings:'⚙',night:'☾'};
function tile(k,sub=''){return `<button class="tile" data-action="nav:${k}" data-help="${k}"><span class="icon">${icons[k]||'✦'}</span><span><strong>${t(k)}</strong>${sub?`<small>${sub}</small>`:''}</span></button>`}
function nav(p){if(overlayCleanup){overlayCleanup();overlayCleanup=null}document.querySelectorAll('.overlay').forEach(e=>e.remove());page=p;render();window.scrollTo(0,0)}
function render(){document.querySelector('.site-notice').hidden=page!=='home';document.getElementById('creatorCredit').hidden=page!=='home';clearInterval(afterRender.clock);document.documentElement.lang=lang;document.body.classList.toggle('dark',!!S.settings.dark);document.body.classList.toggle('large',!!S.settings.large);$('lang').value=lang;document.querySelectorAll('[data-key]').forEach(e=>e.textContent=t(e.dataset.key));updateHelpButtons();$('helpBanner').hidden=!helpMode;$('helpBanner').textContent=L('説明モード：対象を３秒長押し／もう一度「?」で解除','Help mode: hold an item for 3 seconds. Tap ? to exit.','Mode aide : appui de 3 secondes. Touchez ? pour quitter.');const views={home:homeView,diary:diaryView,vitals:vitalsView,women:womenView,meds:medsView,plans:plansView,quiz:quizView,games:gamesView,fortune:fortuneView,frame:frameView,phone:phoneView,calendar:calendarView,search:searchView,trash:trashView,backup:backupView,settings:settingsView,night:nightView};$('app').innerHTML=views[page]?views[page]():homeView();afterRender()}
function title(k){return `<h1 data-help="${k}">${t(k)}</h1>`}
function homeView(){const hidden=S.settings.hidden||[];return `<div class="brand" data-help="mirror" data-hold="mirror"><img src="logo.png" alt="Watashi Plus Watashi Plus" draggable="false"><small>${L('ロゴを１秒長押しで手鏡','Hold logo 1 second for mirror','Appuyez 1 seconde sur le logo : miroir')}</small></div><div class="row"><span class="chip">${new Date().toLocaleDateString({ja:'ja-JP',en:'en-GB',fr:'fr-FR'}[lang],{year:'numeric',month:'long',day:'numeric',weekday:'short'})}</span><small>${t('testing')}</small></div><h2>${L('今日も、自分のペースで。','Today, at your own pace.','Aujourd’hui, à votre rythme.')}</h2><button class="tile hero" data-action="nav:diary" data-help="diary"><span class="icon">📖</span><span><strong>${t('diary')}</strong><small>${L('写真も、ひとことも。','A photo, a few words.','Une photo, quelques mots.')}</small></span><span>›</span></button><h2>${L('からだと暮らし','Health & everyday life','Santé et quotidien')}</h2><div class="grid">${['vitals','women','meds','plans','calendar'].filter(k=>!hidden.includes(k)).map(k=>tile(k)).join('')}</div><h2>${L('ひと息の時間','A little break','Une petite pause')}</h2><div class="grid">${['quiz','games','fortune','frame','night'].filter(k=>!hidden.includes(k)).map(k=>tile(k)).join('')}</div><h2>${L('道具箱','Tools','Outils')}</h2><div class="grid">${['phone','search','backup','trash','settings'].map(k=>tile(k)).join('')}</div>${ownerView()}<footer>${L('個人の記録はこの端末に保存。こまめにバックアップを。','Personal records stay on this device. Back up regularly.','Données conservées sur cet appareil. Sauvegardez régulièrement.')}</footer>`}
function ownerView(){return `<section class="card" style="margin-top:24px" data-help="owner"><h2>${t('owner')}</h2><small>${L('各欄を２秒長押しで編集。編集ボタンでも開けます。','Hold a field for 2 seconds to edit, or use Edit.','Appui de 2 secondes pour modifier, ou bouton Modifier.')}</small><div class="checkrow" style="margin:12px 0"><input id="ownerVisible" type="checkbox" ${S.settings.ownerVisible?'checked':''}><label for="ownerVisible">${L('この情報を表示する','Show this information','Afficher ces informations')}</label></div>${S.settings.ownerVisible?`<div class="row"><div data-hold="owner" data-help="owner">${S.owner.photo?`<img class="avatar" src="${safeImage(S.owner.photo)}" alt="${t('photo')}">`:'◯ '+t('photo')}</div><div>${btn(t('edit'),'owner','','owner')}</div></div>${['name','address','tel','hospital','hospitalTel','doctor','emergency'].map(k=>`<div class="owner-field" data-hold="owner" data-help="owner"><strong>${t(k)}</strong>：${esc(S.owner[k]||t('unregistered'))}</div>`).join('')}`:btn(L('登録・編集','Register / edit','Saisir / modifier'),'owner','','owner')}<p class="muted" style="margin-top:12px">${L('登録・表示は任意です。ロック画面からは見られません。','Optional. Not accessible from the lock screen.','Facultatif. Non accessible depuis l’écran verrouillé.')}</p></section>`}
function safeImage(s){return /^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(s||'')?s:''}
function entryCard(e){return `<article class="entry" data-help="${e.kind}"><div class="row"><strong>${esc(e.title||t(e.kind)||'')}</strong><small>${stamp(e.when)}</small></div>${e.body?`<p class="body">${esc(e.body)}</p>`:''}${e.values?`<p>${Object.entries(e.values).filter(([k,v])=>v!==''&&v!=null).map(([k,v])=>`${esc(labelFor(k))}：${esc(valueLabel(k,v))}`).join(' ／ ')}</p>`:''}${e.photos?.length?`<div class="photo-grid">${e.photos.map((p,i)=>`<img src="${safeImage(p.data)}" alt="${esc(p.caption||t('photo'))}" data-action="photo:${e.id}:${i}" data-help="photo">`).join('')}</div>`:''}<div class="row" style="margin-top:10px">${['diary','vitals','women'].includes(e.kind)?btn(t('edit'),'edit:'+e.id):''}${btn(t('del'),'trash:'+e.id,'danger')}</div></article>`}
function listEntries(arr){return arr.length?arr.slice(0,100).map(entryCard).join('')+(arr.length>100?`<p>${L('最新100件を表示。検索や期間指定で絞り込んでください。','Showing latest 100. Narrow the date range or search.','100 derniers éléments. Affinez la recherche.')}</p>`:''):`<p class="muted">${t('empty')}</p>`}
function diaryView(){return title('diary')+`<p>${L('診察の質問、配信のネタ、持ち物も自由に。','Questions, ideas, lists — anything you like.','Questions, idées, listes : écrivez librement.')}</p><div class="row">${btn(t('new'),'new:diary','primary')}${btn(t('search'),'nav:search')}</div><section class="card" style="margin-top:16px">${listEntries(active().filter(e=>e.kind==='diary'))}</section>`}
function active(){return S.entries.filter(e=>!e.deleted).sort((a,b)=>b.when.localeCompare(a.when))}
const valueOptions={mood:[['good','😊', 'Good','Bien'],['okay','😐','Okay','Moyen'],['low','😔','Low','Bas'],['tired','😴','Tired','Fatigué']],bowel:[['normal','普通','Normal','Normal'],['hard','硬い','Hard','Dur'],['loose','軟らかい','Loose','Mou'],['diarrhea','下痢','Diarrhoea','Diarrhée'],['none','なし','None','Aucun']],condition:[['waking','起床時','On waking','Au réveil'],['before','食前','Before meal','Avant repas'],['after','食後','After meal','Après repas'],['other','その他','Other','Autre']]};
function opts(k){return [['',L('未記入','Not recorded','Non renseigné')],...(valueOptions[k]||[]).map(v=>[v[0],L(v[1],v[2],v[3])])]}
function valueLabel(k,v){const a=(valueOptions[k]||W.find(w=>w[0]===k)?.[2]||[]).find(x=>x[0]===v);return a?L(a[1],a[2],a[3]):v}
function labelFor(k){return I[k]?t(k):(W.find(x=>x[0]===k)?.[1]?.[{ja:0,en:1,fr:2}[lang]]||k)}
function modal(html){const d=$('modal');d.innerHTML=`<div class="modal-tools">${btn('TOP','goTop')}${btn('?','toggleHelp','','help')}${btn(t('close'),'cancel')}</div><div id="modalHelpNotice"></div>`+html;d.showModal();updateHelpButtons();bindDials();}
function modalButtons(action='commit'){return `<div class="row">${btn(t('cancel'),'cancel')}${btn(t('save'),action,'primary')}</div>`}
let editId=null,editPhotos=[],editToken=0;
function dial(k,min,max,step,unit,value){return `<label class="checkrow"><input class="check" type="checkbox" id="on-${k}" ${value!=null?'checked':''}>${t(k)} (${unit})</label><div class="dial">${btn('−','step:'+k+':-1')}<input type="number" id="v-${k}" min="${min}" max="${max}" step="${step}" value="${value??min}">${btn('＋','step:'+k+':1')}</div>`}
function newEntry(kind,id){const session=++editToken;const e=id?S.entries.find(x=>x.id===id):null;editId=id||null;editPhotos=structuredClone(e?.photos||[]);const v=e?.values||{};let fields=field(t('date'),'entryWhen',e?.when||localDT(),'datetime-local','required')+field(t('title'),'entryTitle',e?.title||'');if(kind==='diary')fields+=select(t('category'),'entryCategory',[["",L('自由','Free','Libre')],['food',L('食事','Food','Repas')],['hospital',L('通院・入院','Hospital','Hôpital')],['ideas',L('配信・アイデア','Ideas','Idées')],['check',L('持ち物・チェック','Checklist','Liste')]],e?.category||'')+select(t('mood'),'mood',opts('mood'),v.mood||'')+select(t('bowel'),'bowel',opts('bowel'),v.bowel||'')+select(L('睡眠','Sleep','Sommeil'),'sleep',opts('sleep'),v.sleep||'')+select(L('だるさ・生活への影響','Fatigue / daily impact','Fatigue / retentissement'),'fatigue',opts('fatigue'),v.fatigue||'');if(kind==='vitals')fields+=dial('temp',30,45,.1,'℃',v.temp)+dial('sys',40,300,1,'mmHg',v.sys)+dial('dia',20,200,1,'mmHg',v.dia)+dial('glucose',10,700,1,'mg/dL',v.glucose)+select(t('condition'),'condition',opts('condition'),v.condition||'')+dial('pulse',20,250,1,L('回/分','bpm','bpm'),v.pulse)+`<small>${L('入力範囲外の測定値や「HI・LO」は、備考にそのまま残してください。','Values outside the dial range: write the exact reading in Notes.','Hors plage : notez la valeur exacte dans les notes.')}</small>`;if(kind==='women')fields+=womenFields(v);fields+=area(t('text'),'entryBody',e?.body||'')+`<label>${t('photo')} <input id="entryFiles" type="file" accept="image/*" multiple></label><small>${L('写真は長辺1600px以内に縮小して保存します。原本は別途保管してください。','Photos are resized to max 1600px. Keep originals separately.','Photos réduites à 1600 px maximum. Conservez les originaux.')}</small><div id="editPhotos" class="photo-grid"></div>`;modal(`<h1>${t(kind)}</h1><form id="entryForm" data-help="${kind}">${!id?`<p class="notice">${L('新規入力です。過去の記録を変更する場合は、一覧の「編集」を選んでください。','New entry. To change an existing record, select Edit in the list.','Nouvelle note. Pour modifier une note, utilisez Modifier dans la liste.')}</p>`:''}${fields}<div id="entryErr" role="alert"></div>${modalButtons('commit:'+kind)}</form>`);showEditPhotos();$('entryFiles').onchange=async ev=>{const input=ev.target;input.disabled=true;try{for(const f of input.files){const data=await imageData(f);if(session!==editToken||!$('modal').open)return;editPhotos.push({data,caption:f.name})}if($('editPhotos'))showEditPhotos()}catch(e){toast(e.message)}finally{input.disabled=false;input.value=''}}}
function showEditPhotos(){$('editPhotos').innerHTML=editPhotos.map((p,i)=>`<div><img src="${safeImage(p.data)}" alt="${t('photo')}">${btn('×','removePhoto:'+i)}</div>`).join('')}
async function imageData(file){if(file.size>30*1024*1024)throw Error(L('写真は１枚30MB以内にしてください','Use photos under 30MB','Photo : 30 Mo maximum'));return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Read error'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(Error(L('この画像形式は読み込めません。JPEGなどでお試しください。','Cannot read this image. Try JPEG.','Image illisible. Essayez JPEG.')));img.onload=()=>{const factor=Math.min(1,1600/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*factor);c.height=Math.round(img.height*factor);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.83))};img.src=reader.result};reader.readAsDataURL(file)})}
async function commitEntry(kind){if(!$('entryWhen').value){toast(L('日時を入力してください','Enter a date','Saisissez une date'));return}if($('entryFiles').disabled){toast(L('写真の処理中です','Processing photos','Traitement des photos'));return}const priorValues=S.entries.find(x=>x.id===editId)?.values||{};const values=kind==='women'?structuredClone(priorValues):{};if(kind==='diary'){values.mood=$('mood').value;values.bowel=$('bowel').value;values.sleep=$('sleep').value;values.fatigue=$('fatigue').value}if(kind==='vitals'){for(const k of ['temp','sys','dia','glucose','pulse'])if($('on-'+k).checked)values[k]=Number($('v-'+k).value);values.condition=$('condition').value}if(kind==='women')for(const w of W)if($('w-'+w[0]))values[w[0]]=$('w-'+w[0]).value;const old=S.entries.find(e=>e.id===editId);const e={...old,id:editId||uid(),kind,when:$('entryWhen').value,title:$('entryTitle').value,body:$('entryBody').value,category:$('entryCategory')?.value||'',values,photos:structuredClone(editPhotos),modified:Date.now()};if(!e.body.trim()&&!e.title.trim()&&!e.photos.length&&!Object.values(values).some(v=>v!=='')){toast(L('何か１つ記入してください','Add at least one item','Ajoutez au moins un élément'));return}if(await mutate(n=>{const i=n.entries.findIndex(x=>x.id===e.id);if(i>=0)n.entries[i]=e;else n.entries.push(e)})){closeModal();toast(t('saved'))}}
function closeModal(){editToken++;stopRecord();recordToken++;$('modal').close();setHelpMode(false)}
const W=[['bleed',['出血','Bleeding','Saignements'],[['none','なし','None','Aucun'],['spot','少量・点状','Spotting','Traces'],['light','少なめ','Light','Faible'],['moderate','中程度','Moderate','Modéré'],['heavy','多い','Heavy','Abondant']]],['discharge',['おりものの変化','Discharge changes','Pertes vaginales'],[['none','変化なし','Unchanged','Sans changement'],['amount','量の変化','Amount changed','Quantité modifiée'],['color','色の変化','Colour changed','Couleur modifiée'],['odor','においの変化','Odour changed','Odeur modifiée']]],['pain',['下腹部・骨盤の痛み','Pelvic / lower abdominal pain','Douleur pelvienne'],[['none','なし','None','Aucune'],['mild','軽い','Mild','Légère'],['medium','中程度','Moderate','Modérée'],['strong','強い','Severe','Forte']]],['urine',['排尿の変化','Urinary changes','Troubles urinaires'],[['none','なし','None','Aucun'],['difficult','出にくい','Difficulty','Difficulté'],['pain','痛い','Pain','Douleur'],['leak','尿漏れ','Leakage','Fuites']]],['swelling',['脚のむくみ','Leg swelling','Jambes gonflées'],[['none','なし','None','Aucune'],['left','左','Left','Gauche'],['right','右','Right','Droite'],['both','両方','Both','Deux côtés']]],['flush',['ほてり・寝汗','Hot flushes / night sweats','Bouffées de chaleur / sueurs'],[['none','なし','None','Aucune'],['mild','軽い','Mild','Légères'],['medium','中程度','Moderate','Modérées'],['strong','強い','Severe','Fortes']]],['menstruation',['月経','Menstruation','Règles'],[['start','開始','Started','Début'],['ongoing','継続中','Ongoing','En cours'],['end','終了','Ended','Fin'],['none','なし','None','Aucune']]]];
let range=30,metric='temp',glucoseFilter='';
function vitalsView(){return title('vitals')+btn(t('new'),'new:vitals','primary')+`<section class="card" style="margin-top:16px"><div class="tabs">${['temp','sys','glucose','pulse'].map(k=>btn(t(k==='sys'?'bp':k),`metric:${k}`,metric===k?'primary':'')).join('')}</div>${field(L('表示の終了日','Display end date','Date de fin'),'vitalEnd',vitalEnd,'date')}${select(t('period'),'range',[[7,L('１週間','1 week','1 semaine')],[30,L('１か月','1 month','1 mois')],[90,L('３か月','3 months','3 mois')],[365,L('１年','1 year','1 an')],[0,t('all')]].map(x=>[String(x[0]),x[1]]),String(range))}${metric==='glucose'?select(t('condition'),'glucoseFilter',[['',L('すべて','All','Tous')],...opts('condition').slice(1)],glucoseFilter):''}<div id="chart">${chartView()}</div></section><section class="card">${listEntries(vitalEntries())}</section>`}
function vitalEntries(){const anchor=new Date(vitalEnd+'T12:00:00'),cutoff=range?day(new Date(anchor.getTime()-(range-1)*86400000)):'';return active().filter(e=>e.kind==='vitals'&&e.when.slice(0,10)>=cutoff&&e.when.slice(0,10)<=vitalEnd&&(!glucoseFilter||metric!=='glucose'||e.values.condition===glucoseFilter))}
function chartView(){const entries=vitalEntries().slice().reverse(),keys=metric==='sys'?['sys','dia']:[metric],series=keys.map(k=>entries.filter(e=>Number.isFinite(e.values[k])).map(e=>({x:new Date(e.when).getTime(),y:e.values[k],when:e.when}))),points=series.flat();if(!points.length)return `<p>${t('empty')}</p>`;const minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x));let minY=Math.min(...points.map(p=>p.y)),maxY=Math.max(...points.map(p=>p.y));const pad=Math.max((maxY-minY)*.15,metric==='temp'?.2:5);minY-=pad;maxY+=pad;const X=x=>55+(x-minX)/(maxX-minX||1)*620,Y=y=>235-(y-minY)/(maxY-minY)*210;let svg=`<svg class="chart" viewBox="0 0 710 285" role="img" aria-label="${esc(t('vitals'))}">`;for(let i=0;i<5;i++){const val=minY+(maxY-minY)*i/4,y=Y(val);svg+=`<line x1="55" x2="680" y1="${y}" y2="${y}" stroke="var(--line)"/><text x="4" y="${y+4}" fill="var(--muted)" font-size="12">${val.toFixed(metric==='temp'?1:0)}</text>`}const colors=['#b84d66','#407da2'];series.forEach((p,i)=>{svg+=`<polyline fill="none" stroke="${colors[i]}" stroke-width="2" points="${p.map(a=>`${X(a.x)},${Y(a.y)}`).join(' ')}"/>`+p.map(a=>`<circle cx="${X(a.x)}" cy="${Y(a.y)}" r="4" fill="${colors[i]}"><title>${esc(stamp(a.when))} : ${a.y}</title></circle>`).join('')});svg+=`<text x="55" y="270" fill="var(--muted)" font-size="12">${day(new Date(minX))}</text><text x="675" y="270" text-anchor="end" fill="var(--muted)" font-size="12">${day(new Date(maxX))}</text></svg>`;return `<p>${metric==='temp'?'℃':metric==='glucose'?'mg/dL':metric==='pulse'?'bpm':'mmHg'}</p>`+svg+`<div class="legend">${keys.map((k,i)=>`<span style="color:${colors[i]}">● ${t(k)}</span>`).join('')}</div><small>${L('左右の点は測定日時順。点の間は未測定です。数値は下の記録で確認できます。','Points follow measurement times. Gaps do not imply measurements. Exact readings are listed below.','Points selon les dates de mesure. Valeurs exactes dans la liste ci-dessous.')}</small>`}
function womenView(){return womenMonthView()}
function womenSettings(){modal(`<h1>${t('women')}</h1>${W.map(w=>`<label class="checkrow" style="margin:14px 0"><input type="checkbox" id="show-${w[0]}" ${S.settings.hiddenWomen?.includes(w[0])?'':'checked'}>${L(...w[1])}</label>`).join('')}${modalButtons('saveWomenSettings')}`)}
function medsView(){return title('meds')+`<p class="notice">${L('通知の確認と服用記録は別です。飲んだか不明な場合、追加服用をアプリで判断しないでください。','Confirming an alert does not record a dose. If uncertain, do not use this app to decide on an extra dose.','Confirmer une alerte ne note pas une prise. En cas de doute, ne décidez pas d’une dose supplémentaire ici.')}</p>${btn(t('add'),'medEdit:new','primary')}<div style="margin-top:15px">${S.medications.filter(m=>!m.deleted).map(m=>`<section class="card"><h2>${esc(m.name)}</h2><p>${esc(m.dose)} · ${esc(m.times)}</p>${m.remaining!==''&&m.remaining!=null?`<p>${L('残数','Remaining','Restant')}：${esc(m.remaining)} ${stockUnit(m)}</p>`:''}<p>${esc(m.note)}</p>${medicineLinks(m)}<small>${L('直近の記録','Last record','Dernière note')}：${lastDose(m.id)}</small><div class="row" style="margin-top:12px">${btn(L('服用済み','Taken','Pris'),'dose:'+m.id+':taken','primary')}${btn(L('飲んだか不明','Unsure','Incertain'),'dose:'+m.id+':unsure')}</div><div class="row" style="margin-top:8px">${btn(t('edit'),'medEdit:'+m.id)}${btn(t('del'),'medTrash:'+m.id,'danger')}</div></section>`).join('')}</div><h2>${L('服用履歴','Dose history','Historique des prises')}</h2><section class="card">${listEntries(active().filter(e=>e.kind==='dose'))}</section>`}
function lastDose(id){const e=active().find(e=>e.medicationId===id);return e?esc(stamp(e.when)+' '+e.body):t('empty')}
function medEdit(id){const m=S.medications.find(x=>x.id===id)||{};modal(`<h1>${t('meds')}</h1>${field(L('薬名','Medication name','Nom du médicament'),'medName',m.name)}${field(L('製品の規格（例：１錠あたり5mg）','Product strength (e.g. 5 mg per tablet)','Dosage du produit (ex. 5 mg par comprimé)'),'medStrength',m.strength||'')}${field(L('１回の服用量：数字','Dose per administration: number','Quantité par prise : nombre'),'medDoseNumber',m.amount??'', 'number','min="0" step="any" inputmode="decimal"')}${select(L('服用量の単位','Dose unit','Unité de prise'),'medUnit',DOSE_UNITS,m.unit||'tablet')}${m.dose&&m.amount==null?`<p class="notice">${L('旧記録の量（数字欄へ自動変換しません）','Legacy dose (not auto-converted)','Ancienne dose (non convertie)')}：${esc(m.dose)}</p>`:''}${field(L('予定時刻・条件','Times / instructions','Horaires / consignes'),'medTimes',m.times)}${select(L('残数（任意・現物と照合）','Remaining (optional; check actual supply)','Restant (facultatif, vérifier le stock)'),'medRemaining',[['',L('管理しない','Not tracked','Non suivi')],...Array.from({length:1001},(_,i)=>[String(i),String(i)])],m.remaining==null?'':String(m.remaining))}${area(t('notes'),'medNote',m.note)}${field(L('確認済みの公式薬剤情報URL（任意）','Verified official medicine URL (optional)','URL officielle vérifiée (facultatif)'),'medInfoUrl',m.infoUrl||'','url')}<p>${L('薬効・副作用はPMDAの公式情報で確認します。薬名・規格を照合してください。','Check effects and side effects on PMDA; match the name and strength.','Vérifiez les effets avec PMDA et le nom/dosage exacts.')}</p>${modalButtons('medSave:'+id)}`)}
async function recordDose(id,status){const m=S.medications.find(x=>x.id===id);if(status==='taken'&&!confirm(L('服用済みとして記録しますか？','Record as taken?','Noter comme pris ?')))return;await mutate(n=>n.entries.push({id:uid(),kind:'dose',medicationId:id,when:localDT(),title:m.name,body:status==='taken'?L('服用済み','Taken','Pris'):L('飲んだか不明','Unsure','Incertain'),photos:[]}));toast(t('saved'))}
function plansView(){return title('plans')+`<p class="notice">${L('音声はこの画面を開いている間の補助機能です。ロック中・別アプリ使用中の通知はできません。重要な予定はiPhoneのアラームも併用してください。','Voice reminders work only while this page is active. No reliable alerts while locked or in another app. Use iPhone alarms for important reminders.','Rappels vocaux uniquement sur cette page active. Pas d’alerte fiable écran verrouillé. Utilisez aussi les alarmes iPhone.')}</p>${btn(t('add'),'planEdit:new','primary')} ${btn(L('音声を試す','Test voice','Tester la voix'),'voiceTest')}<div style="margin-top:16px">${S.plans.filter(p=>!p.deleted).sort((a,b)=>a.time.localeCompare(b.time)).map(p=>`<section class="card"><h2>${esc(p.time)}　${esc(p.title)}</h2><p>${esc(p.date)} · ${esc(repeatLabel(p.repeat))}</p><div class="row">${btn(p.enabled?L('有効','Enabled','Actif'):L('停止中','Paused','En pause'),'planToggle:'+p.id)}${btn(L('試し聞き','Listen','Écouter'),'planPlay:'+p.id)}${btn(t('edit'),'planEdit:'+p.id)}${btn(t('del'),'planTrash:'+p.id,'danger')}</div></section>`).join('')}</div>`}
const repeatLabel=r=>r==='daily'?L('毎日','Daily','Chaque jour'):r==='weekdays'?L('月〜金','Mon–Fri','Lun–ven'):L('指定日のみ','Once','Une fois');
function planEdit(id){const p=S.plans.find(x=>x.id===id)||{};pendingSound=p.sound||null;modal(`<h1>${t('plans')}</h1>${field(t('title'),'planTitle',p.title)}${field(L('日付','Date','Date'),'planDate',p.date||day(),'date')}${field(L('時刻','Time','Heure'),'planTime',p.time||'09:00','time')}${select(L('繰り返し','Repeat','Répéter'),'planRepeat',[['once',L('指定日のみ','Once','Une fois')],['daily',L('毎日','Daily','Chaque jour')],['weekdays',L('月〜金','Mon–Fri','Lun–ven')]],p.repeat||'once')}<div class="row">${btn(L('録音開始','Record voice','Enregistrer la voix'),'recordStart')}${btn(L('録音停止','Stop recording','Arrêter'),'recordStop')}${btn(L('文字読み上げに戻す','Use text-to-speech','Lire le texte'),'recordClear')}</div><p id="recordStatus">${p.sound?L('録音あり','Voice recorded','Voix enregistrée'):L('文字を読み上げます','Text will be spoken','Le texte sera lu')}</p>${modalButtons('planSave:'+id)}`)}
let recordToken=0,recordProcessing=false;
async function startRecord(){const token=++recordToken;try{if(recording?.state==='recording')return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error(L('この環境では録音できません。文字読み上げを使えます。','Recording unavailable. Use text-to-speech.','Enregistrement indisponible. Utilisez la synthèse vocale.'));const stream=await navigator.mediaDevices.getUserMedia({audio:true});audioChunks=[];recording=new MediaRecorder(stream);recording.ondataavailable=e=>{if(e.data.size)audioChunks.push(e.data)};recording.onstop=()=>{recordProcessing=true;const reader=new FileReader();reader.onload=()=>{recordProcessing=false;if(token!==recordToken||!$('modal').open)return;pendingSound=reader.result;if($('recordStatus'))$('recordStatus').textContent=L('録音を保存できます','Recording ready','Enregistrement prêt')};reader.readAsDataURL(new Blob(audioChunks,{type:recording.mimeType}));stream.getTracks().forEach(t=>t.stop());recording=null};recording.start();$('recordStatus').textContent=L('録音中（最長20秒）','Recording (max 20 seconds)','Enregistrement (20 s max)');clearTimeout(startRecord.limit);startRecord.limit=setTimeout(stopRecord,20000)}catch(e){toast(e.message)}}
function stopRecord(){clearTimeout(startRecord.limit);if(recording?.state==='recording')recording.stop()}
function speak(text){if(!window.speechSynthesis){toast(L('読み上げ非対応です','Speech unavailable','Synthèse vocale indisponible'));return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang={ja:'ja-JP',en:'en-US',fr:'fr-FR'}[lang];speechSynthesis.speak(u)}
function playPlan(p){if(p.sound){const a=new Audio(p.sound);a.play().catch(()=>toast(L('音声を再生できません。音量と設定を確認してください。','Audio blocked. Check volume and settings.','Audio bloqué. Vérifiez le volume.')))}else speak(p.title)}
let planShown=new Set();function tickPlans(){if(page!=='plans'||document.visibilityState!=='visible')return;const now=new Date(),date=day(now),time=localDT(now).slice(11,16);for(const p of S?.plans||[]){const key=p.id+date;if(!p.enabled||p.deleted||p.time!==time||planShown.has(key)||p.lastAlert===date)continue;const match=p.repeat==='daily'||p.repeat==='weekdays'&&now.getDay()>0&&now.getDay()<6||p.repeat==='once'&&p.date===date;if(match){planShown.add(key);mutate(n=>{n.plans.find(x=>x.id===p.id).lastAlert=date},{undo:false,refresh:false});playPlan(p);toast(p.title)}}}
function phoneView(){return title('phone')+`<p>${L('横スライドで発信確認。名前部分を２秒長押しで編集。','Slide to confirm a call. Hold the name 2 seconds to edit.','Glissez pour appeler. Appui de 2 secondes pour modifier.')}</p><p class="muted">${L('iPhone側の確認後に発信します。','iPhone asks for confirmation before calling.','L’iPhone demande confirmation avant l’appel.')}</p>${S.contacts.map((c,i)=>`<div class="slider" data-contact="${i}" data-help="phone"><div class="track"></div><div class="handle" data-hold="contact:${i}" data-help="phone"><strong>${String(i+1).padStart(2,'0')}　${esc(c.name||t('unregistered'))}</strong><small>${esc(c.number||'→')}</small></div><span class="end">☎</span></div>`).join('')}`}
function contactEdit(i){const c=S.contacts[i];modal(`<h1>${t('phone')} ${i+1}</h1>${field(t('name'),'contactName',c.name)}${field(t('tel'),'contactNumber',c.number,'tel','inputmode="tel"')}${modalButtons('contactSave:'+i)}`)}
function ownerEdit(){modal(`<h1>${t('owner')}</h1><label>${t('photo')}<input id="ownerPhoto" type="file" accept="image/*"></label>${['name','address','tel','hospital','hospitalTel','doctor','emergency'].map(k=>field(t(k),'o-'+k,S.owner[k]||'',k==='tel'||k==='hospitalTel'?'tel':'text')).join('')}${modalButtons('ownerSave')}`)}
let calendarMonth=day().slice(0,7),searchText='',searchFrom='',searchTo='';
function calendarView(){const entries=active(),[year,month]=calendarMonth.split('-').map(Number),count=new Date(year,month,0).getDate(),offset=new Date(year,month-1,1).getDay();return title('calendar')+`<div class="card">${field(L('月','Month','Mois'),'calendarMonth',calendarMonth,'month')}<div class="calendar">${L('日 月 火 水 木 金 土','Sun Mon Tue Wed Thu Fri Sat','Dim Lun Mar Mer Jeu Ven Sam').split(' ').map(s=>`<small>${s}</small>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const date=calendarMonth+'-'+String(i+1).padStart(2,'0'),e=entries.filter(e=>e.when.startsWith(date)),img=e.flatMap(e=>e.photos||[])[0];return `<button data-action="dateSearch:${date}" data-help="calendar">${i+1}${img?`<img alt="" src="${safeImage(img.data)}">`:e.length?' ●':''}</button>`}).join('')}</div></div><h2>${L('全記録の年表','All-record timeline','Chronologie de toutes les données')}</h2><section class="card">${listEntries(entries)}</section>`}
function searchView(){return title('search')+`<section class="card">${field(L('本文・見出し・備考を部分一致検索','Search titles, text and notes','Rechercher dans les titres et notes'),'searchText',searchText,'search')}<div class="row">${field(L('開始日','From','Du'),'searchFrom',searchFrom,'date')}${field(L('終了日','To','Au'),'searchTo',searchTo,'date')}</div>${btn(t('search'),'doSearch','primary')} ${btn(L('条件をクリア','Clear filters','Effacer les filtres'),'clearSearch')}</section><section class="card" id="searchResults">${searchResults()}</section>`}
function searchResults(){const q=searchText.normalize('NFKC').toLocaleLowerCase();const arr=active().filter(e=>(!searchFrom||e.when.slice(0,10)>=searchFrom)&&(!searchTo||e.when.slice(0,10)<=searchTo)&&JSON.stringify([e.title,e.body,e.category,...(e.photos||[]).map(p=>p.caption),e.values]).normalize('NFKC').toLocaleLowerCase().includes(q));return `<p>${arr.length} ${L('件','records','éléments')}</p>`+listEntries(arr)}
function trashView(){const entries=S.entries.filter(e=>e.deleted).sort((a,b)=>b.deleted-a.deleted),meds=S.medications.filter(m=>m.deleted),plans=S.plans.filter(p=>p.deleted);return title('trash')+`<p>${L('完全削除するまで残ります。ごみ箱も保存容量を使います。','Items remain until permanently deleted and use storage space.','Les éléments restent et occupent de l’espace jusqu’à suppression définitive.')}</p><section class="card">${[...entries.map(e=>({type:'entry',id:e.id,label:(e.title||t(e.kind))+' · '+stamp(e.when)})),...meds.map(e=>({type:'med',id:e.id,label:e.name})),...plans.map(e=>({type:'plan',id:e.id,label:e.title}))].map(e=>`<div class="entry"><p>${esc(e.label)}</p><div class="row">${btn(t('restore'),`restore:${e.type}:${e.id}`)}${btn(L('完全削除','Delete permanently','Supprimer définitivement'),`purge:${e.type}:${e.id}`,'danger')}</div></div>`).join('')||t('empty')}</section>`}
function backupView(){return title('backup')+`<section class="card"><h2>${L('写真・記録・設定を一式保存','Save photos, records and settings','Sauvegarder photos, données et réglages')}</h2><p>${L('書き出したファイルを、別の端末や自分のクラウドにも保管してください。住所・病歴などが含まれるため、他人には渡さないでください。','Keep the exported file on another device or your own cloud. It contains private health/contact data; do not share it.','Conservez le fichier sur un autre appareil ou votre cloud. Il contient des données privées : ne le partagez pas.')}</p>${btn(L('バックアップを書き出す','Export backup','Exporter la sauvegarde'),'export','primary')}<p style="margin-top:12px">${L('最終書き出し','Last export','Dernier export')}：${S.lastBackup?stamp(S.lastBackup):t('unregistered')}</p><h2>${L('新しいスマホで読み込む','Import on a new phone','Importer sur un nouveau téléphone')}</h2><p>${L('読み込みは現在の記録を置き換えます。先に現在のバックアップを書き出してください。','Import replaces current records. Export the current backup first.','L’import remplace les données actuelles. Exportez-les d’abord.')}</p><input id="importFile" type="file" accept=".json,application/json"><div id="importInfo"></div><p class="notice">${L('ファイルは暗号化されていません。ブラウザーのデータ削除・端末故障では端末内記録も失われます。ごみ箱もバックアップに含みます。','Backup files are not encrypted. Browser data clearing or device loss can erase local records. Trash is included.','Les fichiers ne sont pas chiffrés. Effacer les données du navigateur peut supprimer les notes. La corbeille est incluse.')}</p></section><section class="card"><h2>${L('保存領域','Storage','Stockage')}</h2><p id="storageInfo">…</p></section>`}
function validBackup(v){if(!v||!['watashiplus-backup','koropitaru-backup'].includes(v.format)||v.version!==1||!v.state||v.state.schema!==1)throw Error(L('Watashi Plusの対応バックアップではありません','Unsupported backup format','Format de sauvegarde non pris en charge'));const s=v.state;for(const key of ['entries','medications','plans','contacts','frames'])if(!Array.isArray(s[key]))throw Error('Invalid '+key);if(s.contacts.length!==30||s.frames.length>3||!s.settings||!s.owner||!s.fortune)throw Error('Invalid state');const ids=new Set();for(const e of s.entries){if(typeof e.id!=='string'||ids.has(e.id)||typeof e.kind!=='string'||typeof e.when!=='string'||!Number.isFinite(new Date(e.when).getTime())||!Array.isArray(e.photos))throw Error('Invalid record');ids.add(e.id);if(e.photos.some(p=>!safeImage(p.data)))throw Error('Invalid photo')}for(const m of s.medications)if(!m||typeof m.id!=='string'||typeof m.name!=='string'||typeof m.dose!=='string'||typeof m.times!=='string'||typeof m.note!=='string')throw Error('Invalid medication');for(const f of Object.values(s.fortune))if(!f||!Array.isArray(f.lines)||f.lines.length!==6||f.lines.some(n=>![6,7,8,9].includes(n)))throw Error('Invalid fortune');for(const p of s.frames)if(p!==null&&!safeImage(p))throw Error('Invalid frame');if(s.owner.photo&&!safeImage(s.owner.photo))throw Error('Invalid owner photo');if(s.contacts.some(c=>typeof c.name!=='string'||typeof c.number!=='string'))throw Error('Invalid contacts');if(!['ja','en','fr'].includes(s.settings.lang)||!Array.isArray(s.settings.hidden))throw Error('Invalid settings');for(const p of s.plans)if(typeof p.title!=='string'||typeof p.time!=='string'||!/^\d\d:\d\d$/.test(p.time)||p.sound&&!/^data:audio\/[a-zA-Z0-9.;=+\/-]+;base64,[A-Za-z0-9+/=]+$/.test(p.sound))throw Error('Invalid plan');return normaliseState(s)}
async function exportBackup(){const now=new Date().toISOString();const state=structuredClone(S);state.lastBackup=now;const blob=new Blob([JSON.stringify({format:'watashiplus-backup',version:1,exportedAt:now,state})],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='watashiplus-backup-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);await mutate(n=>n.lastBackup=now,{undo:false});toast(L('書き出しを開始しました。ファイルが保存されたか確認してください。','Export started. Check that the file was saved.','Export lancé. Vérifiez que le fichier a bien été enregistré.'))}
async function importBackup(file){try{if(file.size>350*1024*1024)throw Error(L('350MBを超えるファイルはこの試用版では読み込めません','Trial import limit: 350MB','Limite d’importation : 350 Mo'));const parsed=JSON.parse(await file.text()),s=validBackup(parsed);$('importInfo').innerHTML=`<p>${s.entries.length} ${L('件の記録','records','notes')} / ${s.frames.length} ${t('photo')}</p>${btn(L('確認して置き換える','Confirm replacement','Confirmer le remplacement'),'importConfirm','danger')}`;window.pendingImport=s}catch(e){toast(L('読み込めませんでした：','Import failed: ','Échec de l’import : ')+e.message)}}
function settingsView(){return title('settings')+`<section class="card"><label class="checkrow"><input id="darkSetting" type="checkbox" ${S.settings.dark?'checked':''}>${L('暗い画面','Dark theme','Thème sombre')}</label><br><label class="checkrow"><input id="largeSetting" type="checkbox" ${S.settings.large?'checked':''}>${L('文字を大きく','Larger text','Texte agrandi')}</label><h2>${L('表紙に表示する項目','Visible home sections','Rubriques visibles')}</h2><p>${t('settingsNote')}</p>${['diary','vitals','women','meds','plans','calendar','quiz','games','fortune','frame','night'].map(k=>`<label class="checkrow" style="margin:10px 0"><input id="visible-${k}" type="checkbox" ${S.settings.hidden.includes(k)?'':'checked'}>${t(k)}</label>`).join('')}${btn(t('save'),'saveSettings','primary')}</section><section class="card"><h2>${t('readme')}</h2><p>${L('このアプリは個人の記録と娯楽の道具です。診断・投薬判断や緊急通報の代わりにはなりません。日記や数値は自分で確認し、写真とともに定期的に書き出してください。','A personal record and recreation tool, not diagnosis, medication advice or an emergency service. Check your entries and export backups regularly.','Outil personnel de notes et de loisirs, pas un diagnostic ni un service d’urgence. Vérifiez et sauvegardez vos données.')}</p><p>${L('操作説明：? を押して説明モードをオンにし、対象を３秒長押し。通常時はロゴ１秒で鏡、電話帳・持主情報は２秒で編集できます。','Help: tap ? and hold an item for 3 seconds. Normally, hold the logo 1 second for mirror; contacts and owner fields 2 seconds to edit.','Aide : touchez ?, puis appuyez 3 secondes sur un élément. Logo : 1 s pour le miroir. Contacts et identité : 2 s pour modifier.')}</p><p>${L('画像・音声は外部送信しません。端末の消音、音量、ブラウザー設定によって音声が鳴らない場合があります。','Images and audio are not uploaded. Mute, volume and browser settings may block sound.','Images et sons ne sont pas envoyés. Le mode silencieux et les réglages peuvent bloquer le son.')}</p></section>`}
function frameView(){return title('frame')+`<section class="card"><p>${L('大切な写真を３枚まで。ここで選んだ写真はバックアップにも含まれます。','Up to three favourite photos, included in backups.','Jusqu’à trois photos, incluses dans les sauvegardes.')}</p><div class="photo-grid">${[0,1,2].map(i=>`<div>${S.frames[i]?`<img src="${safeImage(S.frames[i])}" alt="${i+1}" data-action="showFrame:${i}">`:`<div style="height:120px;text-align:center;padding:30px">${i+1} ▣</div>`}<label>${L('写真を選ぶ','Choose photo','Choisir une photo')}<input type="file" accept="image/*" data-frame="${i}"></label></div>`).join('')}</div>${S.frames.length?btn(L('写真立てを開く','Open photo frame','Ouvrir le cadre'),'showFrame:0','primary'):''}<p class="muted">${L('最初の３枚は未提供です。今はご自身の写真で試せます。','The three gift photos are not supplied yet. You can try your own.','Les trois photos du cadeau restent à fournir. Essayez les vôtres.')}</p></section>`}
function showPhotos(photos,index=0,mirror=false){if(!photos.length)return;let i=index,controls=true,startX=0;const el=document.createElement('div');el.className='overlay frame';el.innerHTML=`<div class="controls">${btn(t('back'),'overlayClose')}<span id="frameCount"></span>${btn('‹','framePrev')}${btn('›','frameNext')}</div><img id="bigPhoto" alt="${t('photo')}">`;document.body.append(el);function paint(){$('bigPhoto').src=photos[i];$('frameCount').textContent=`${i+1} / ${photos.length}`}paint();el.addEventListener('click',ev=>{const a=ev.target.closest('[data-action]')?.dataset.action;if(a==='framePrev')i=(i+photos.length-1)%photos.length;else if(a==='frameNext')i=(i+1)%photos.length;else if(!a){controls=!controls;el.querySelector('.controls').style.opacity=controls?'1':'0';return}paint()});el.onpointerdown=e=>startX=e.clientX;el.onpointerup=e=>{if(Math.abs(e.clientX-startX)>45){i=(i+(e.clientX<startX?1:photos.length-1))%photos.length;paint()}}}
async function mirror(){try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera unavailable');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});const el=document.createElement('div');el.className='overlay';el.dataset.hold='mirrorClose';el.dataset.help='mirror';el.innerHTML=`<video autoplay muted playsinline></video><div style="position:absolute;top:15px;right:15px;z-index:2">${btn(t('close'),'overlayClose')}</div><p class="mirror-note">${L('２秒長押しで戻る','Hold 2 seconds to return','Appui de 2 secondes pour revenir')}</p>`;document.body.append(el);el.querySelector('video').srcObject=stream;overlayCleanup=()=>stream.getTracks().forEach(t=>t.stop())}catch(e){toast(L('カメラを開けません。Safariのカメラ許可を確認してください。','Cannot open camera. Check Safari camera permission.','Caméra inaccessible. Vérifiez l’autorisation Safari.'))}}
let audioCtx,noiseNode;function stopNoise(){if(noiseNode){noiseNode.stop();noiseNode=null}if(audioCtx){audioCtx.close();audioCtx=null}}
function nightView(){return title('night')+`<section class="card" style="text-align:center"><div id="clock" style="font-size:3.2em;font-variant-numeric:tabular-nums">${new Date().toLocaleTimeString()}</div><p>${L('音はイヤホンで。周囲への配慮を。','Use headphones and respect others.','Utilisez des écouteurs, respectez les autres.')}</p><div class="row">${btn(L('静かな雨音','Soft rain','Pluie douce'),'noise')}${btn(L('停止','Stop','Arrêter'),'noiseStop')}</div><p>${L('雨音は端末内で合成します。','Rain is synthesized on device.','Pluie synthétisée sur l’appareil.')}</p></section>`}
function playNoise(){stopNoise();try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();const b=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),d=b.getChannelData(0);let prev=0;for(let i=0;i<d.length;i++){prev=(prev+.04*(Math.random()*2-1))/1.04;d[i]=prev*3.5}noiseNode=audioCtx.createBufferSource();noiseNode.buffer=b;noiseNode.loop=true;const gain=audioCtx.createGain();gain.gain.value=.15;noiseNode.connect(gain).connect(audioCtx.destination);noiseNode.start()}catch(e){toast(e.message)}}
const EN_BANK=[];
const quizTemplates=[
['The {n} had disappeared before we arrived at the station.','私たちが駅に着く前に、その{j}は姿を消していました。',['私たちが駅に着いた後、その{j}は姿を消しました。','その{j}が駅に着く前に、私たちは去りました。','私たちはその{j}と一緒に駅に着きました。','私たちは駅でその{j}を見つけました。']],
['If the {n} returns tomorrow, I will stay at home.','明日その{j}が戻ってきたら、私は家にいます。',['明日その{j}が戻らなければ、私は家にいます。','その{j}が戻る前に、私は明日家を出ます。','私は昨日、その{j}と家にいました。','その{j}が家にいるので、私は明日出かけます。']],
['I wish the {n} were here with us right now.','今その{j}が私たちとここにいてくれたらと思います。',['その{j}は今ここで私たちを待っています。','その{j}には今すぐここを去ってほしいです。','私たちは明日その{j}とここへ来ます。','その{j}は今、私たちがここにいることを願っています。']],
['The {n} was not as quiet as I had expected.','その{j}は私が予想していたほど静かではありませんでした。',['その{j}は私の予想より静かでした。','私はその{j}が静かだとは予想していませんでした。','その{j}は私が予想したとおり静かでした。','その{j}が静かだったので、私は驚きませんでした。']],
['Had I noticed the {n}, I would have stopped immediately.','その{j}に気づいていたら、私はすぐに立ち止まったでしょう。',['その{j}に気づいたので、私はすぐに立ち止まりました。','私が立ち止まると、その{j}はすぐに気づきました。','その{j}に気づいても、私は立ち止まらなかったでしょう。','私はその{j}に気づくために、すぐに立ち止まります。']],
['Although the {n} looked tired, it continued walking toward us.','その{j}は疲れて見えましたが、私たちの方へ歩き続けました。',['その{j}は疲れていたので、私たちから離れていきました。','その{j}は疲れて見えましたが、その場にとどまりました。','その{j}は私たちに向かって歩き、疲れて見えなくなりました。','その{j}は元気そうでしたが、歩くのをやめました。']],
['The {n} must have entered through the open window yesterday.','その{j}は昨日、開いた窓から入ったに違いありません。',['その{j}は明日、開いた窓から入らなければなりません。','その{j}は昨日、開いた窓から入れませんでした。','その{j}は昨日、窓を開けなければなりませんでした。','その{j}が昨日窓から入ったはずはありません。']],
['Never before had I seen the {n} move so quickly.','その{j}がこれほど素早く動くのを、それまで見たことがありませんでした。',['その{j}が素早く動くのを、私は何度も見ていました。','その{j}はそれまで一度も動いたことがありませんでした。','私はその{j}がゆっくり動くのを初めて見ました。','その{j}が動く前に、私はいつもそれを見ていました。']],
['The {n} would rather sleep outside than stay in here.','その{j}はここにいるより、外で眠りたいようです。',['その{j}は外で眠るより、ここにいたいようです。','その{j}はここで眠ってから外に出たいようです。','その{j}は外にいるより、ここで眠りたいようです。','その{j}は外でもここでも眠りたくないようです。']],
['No sooner had the {n} appeared than everyone fell silent.','その{j}が現れるとすぐに、全員が静かになりました。',['全員が静かになる前に、その{j}は姿を消しました。','その{j}が現れるより早く、全員が静かになりました。','その{j}は全員が静かになるまで現れませんでした。','その{j}が現れたので、全員が話し始めました。']]
];
const quizNouns=[['cat','猫'],['dog','犬'],['fox','キツネ'],['rabbit','ウサギ'],['deer','シカ'],['bear','クマ'],['wolf','オオカミ'],['horse','馬'],['tiger','トラ'],['lion','ライオン']];
for(const q of quizTemplates)for(const [n,j] of quizNouns){const sub=s=>s.replaceAll('{n}',n).replaceAll('{j}',j);EN_BANK.push({english:sub(q[0]),correct:sub(q[1]),wrong:q[2].map(sub)})}
function seedOf(s){let x=2166136261;for(const c of s)x=Math.imul(x^c.charCodeAt(0),16777619);return x>>>0}
function rng(seed){return ()=>{seed|=0;seed=seed+0x6D2B79F5|0;let n=Math.imul(seed^seed>>>15,1|seed);n^=n+Math.imul(n^n>>>7,61|n);return((n^n>>>14)>>>0)/4294967296}}
function shuffle(a,r=Math.random){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
let quizIndex=null,quizState=null,quizDay=day();
function quizView(){if(quizDay!==day()){quizDay=day();quizIndex=null}if(quizIndex===null)quizIndex=Math.floor(Date.parse(day()+'T00:00:00Z')/86400000)%EN_BANK.length;const q=EN_BANK[quizIndex],r=rng(seedOf(day()+quizIndex));quizState={q,options:shuffle([q.correct,...q.wrong],r),done:false};return title('quiz')+`<p>${L('日替わりの１問。単語の順序から、元の英文の意味を推理してください。','Daily question. Infer the meaning from shuffled words; answers are in Japanese.','Question du jour : retrouvez le sens. Réponses en japonais.')}</p><section class="card"><span class="chip">${quizIndex+1} / ${EN_BANK.length}</span><div class="game-board" id="quizWords">${esc(shuffle(q.english.replace(/[.,]/g,'').split(' '),r).join(' / '))}</div><div class="answers">${quizState.options.map((o,i)=>btn(`${i+1}. ${esc(o)}`,'quizAnswer:'+i)).join('')}</div><p id="quizResult"></p><div class="row">${btn(t('hint'),'quizHint')}${btn(t('question'),'quizNext')}</div></section>`}
function answerQuiz(i){if(quizState.done)return;quizState.done=true;$('quizResult').innerHTML=`<strong class="${quizState.options[i]===quizState.q.correct?'success':'error'}">${quizState.options[i]===quizState.q.correct?t('correct'):t('incorrect')}</strong><p>${esc(quizState.q.english)}</p><p>${esc(quizState.q.correct)}</p>`}
const GAME_NAMES=[['数列の規則','Number sequence','Suite numérique'],['違う数を探す','Odd number out','Nombre intrus'],['天秤の計算','Balance equation','Équilibre'],['暗号を解く','Caesar cipher','Code César'],['曜日の推理','Day of the week','Jour de la semaine'],['時計の角度','Clock angle','Angle des aiguilles'],['握手の数','Handshakes','Poignées de main'],['確率の比較','Probability','Probabilité'],['並び順推理','Ordering clues','Ordre logique'],['条件で絞る','Filter the clues','Filtrer les indices'],['集合の人数','Overlapping sets','Ensembles'],['数の逆算','Reverse calculation','Calcul inverse'],['余りの推理','Remainders','Restes'],['二進数','Binary numbers','Nombres binaires'],['道順の数','Count paths','Compter les chemins'],['論理の否定','Logical negation','Négation logique'],['文字の共通点','Letter patterns','Motifs de lettres'],['暗算の近道','Mental shortcut','Calcul astucieux'],['箱とラベル','Wrong labels','Fausses étiquettes'],['順列の数','Permutations','Permutations'],['最大公約数','Greatest common divisor','PGCD'],['サイコロの目','Opposite die faces','Faces opposées'],['言葉の分類','Word category','Catégorie de mots'],['１つだけ真実','One true statement','Une seule vérité'],['４組の絵合わせ','Pair memory','Paires en mémoire'],['消灯パズル','Lights out','Éteindre les lumières'],['８パズル','Sliding puzzle','Taquin'],['石取り','Take-away strategy','Jeu des pierres'],['昇順タップ','Ascending order','Ordre croissant'],['迷路を抜ける','Mini maze','Petit labyrinthe']];
let gameState=null;
const ri=(r,a,b)=>a+Math.floor(r()*(b-a+1));
function gcd(a,b){while(b)[a,b]=[b,a%b];return a}
function choose(n,k){let x=1;for(let i=1;i<=k;i++)x=x*(n-i+1)/i;return Math.round(x)}
function questionGame(id,r=Math.random){let prompt='',correct='',wrong=[],explain='';const a=ri(r,2,8),b=ri(r,2,7),n=ri(r,3,8),num=(v,dist=[-2,-1,1,2])=>{correct=String(v);wrong=shuffle(dist,r).slice(0,3).map(d=>String(v+d))};
switch(id){case 0:{const step=ri(r,2,6),start=ri(r,1,10);prompt=L('次の数は？','Next number?','Nombre suivant ?')+'\n'+[0,1,2,3].map(i=>start+step*i).join(', ')+', ?';num(start+step*4);explain=L(`差が毎回${step}です。`,`Each difference is ${step}.`,`Chaque écart vaut ${step}.`);break}
case 1:{const base=ri(r,2,8),arr=[base*2,base*4,base*6,base*8+1];prompt=L('１つだけ奇数です。どれ？','Which is the only odd number?','Quel est le seul nombre impair ?');correct=String(arr[3]);wrong=arr.slice(0,3).map(String);explain=L('２で割り切れない数を選びます。','Odd numbers are not divisible by 2.','Un impair n’est pas divisible par 2.');break}
case 2:prompt=`${a} × □ + ${b} = ${a*n+b}\n`+L('□に入る整数は？','Which integer is □?','Quel entier remplace □ ?');num(n);explain=`(${a*n+b} − ${b}) ÷ ${a} = ${n}`;break;
case 3:{const words=['CAT','DOG','SUN','MAP','KEY','BOX'],w=words[ri(r,0,5)],shift=ri(r,1,3),cipher=w.split('').map(c=>String.fromCharCode((c.charCodeAt(0)-65+shift)%26+65)).join('');prompt=L(`各文字をアルファベット順に${shift}文字進めた暗号です。元の単語は？`,`Letters were shifted forward ${shift} places. Decode:`,`Lettres décalées de ${shift} rangs. Décodez :`)+'\n'+cipher;correct=w;wrong=words.filter(x=>x!==w).slice(0,3);explain=L('各文字を同じ数だけ戻します。','Shift each letter back.','Reculez chaque lettre.');break}
case 4:{const days=L('日曜日,月曜日,火曜日,水曜日,木曜日,金曜日,土曜日','Sunday,Monday,Tuesday,Wednesday,Thursday,Friday,Saturday','dimanche,lundi,mardi,mercredi,jeudi,vendredi,samedi').split(','),start=ri(r,0,6),d=ri(r,8,30);prompt=L(`今日は${days[start]}。${d}日後は？`,`Today is ${days[start]}. What day is ${d} days later?`,`Nous sommes ${days[start]}. Quel jour dans ${d} jours ?`);correct=days[(start+d)%7];wrong=days.filter(x=>x!==correct).slice(0,3);explain=L('７日で同じ曜日に戻ります。','Weekdays repeat every 7 days.','Les jours se répètent tous les 7 jours.');break}
case 5:{const h=ri(r,1,11),v=Math.min(h*30,360-h*30);prompt=L(`${h}時ちょうど。長針と短針の小さい方の角度は？`, `At exactly ${h}:00, what is the smaller angle between the hands?`,`À ${h} h pile, quel est le plus petit angle des aiguilles ?`);num(v,[-30,-15,15,30]);explain=L('１時間の目盛りは30度です。','Each hour mark is 30 degrees.','Un intervalle d’heure vaut 30 degrés.');break}
case 6:prompt=L(`${n}人が、全員と１回ずつ握手。合計は？`,`${n} people each shake hands once with everyone else. Total?`,`${n} personnes se serrent toutes la main une fois. Total ?`);num(n*(n-1)/2);explain=`${n} × ${n-1} ÷ 2`;break;
case 7:prompt=L(`袋に赤${a}個、青${b}個。１個引いて赤の確率は？`,`A bag has ${a} red and ${b} blue balls. Probability of red?`,`Un sac contient ${a} rouges et ${b} bleues. Probabilité d’une rouge ?`);correct=`${a}/${a+b}`;wrong=[`${b}/${a+b}`,`${a}/${a+b+1}`,`1/${a+b}`].filter(x=>x!==correct);if(wrong.length<3)wrong.push('0');explain=L('赤の個数 ÷ 全体の個数。','Red count divided by total count.','Nombre de rouges divisé par le total.');break;
case 8:{const order=shuffle(['A','B','C','D'],r);prompt=L('左から右への並び。次の条件で一番左は？','Left-to-right order. Who is leftmost?','Ordre de gauche à droite. Qui est à gauche ?')+`\n${order[0]} < ${order[1]}\n${order[1]} < ${order[2]}\n${order[2]} < ${order[3]}`;correct=order[0];wrong=order.slice(1);explain=order.join(' → ');break}
case 9:{const target=ri(r,2,9)*2;prompt=L(`偶数、${target-2}より大きく、${target+2}より小さい整数は？`,`Which integer is even, greater than ${target-2}, and less than ${target+2}?`,`Quel entier pair est supérieur à ${target-2} et inférieur à ${target+2} ?`);num(target);explain=L('３つの条件を同時に満たす数です。','All three conditions must hold.','Les trois conditions doivent être vraies.');break}
case 10:{const both=ri(r,1,Math.min(a,b)-1);prompt=L(`紅茶好き${a}人、珈琲好き${b}人、両方好き${both}人。少なくとも片方を好きな人数は？`,`${a} like tea, ${b} like coffee, ${both} like both. How many like at least one?`,`${a} aiment le thé, ${b} le café, ${both} les deux. Combien aiment au moins l’un ?`);num(a+b-both);explain=`${a} + ${b} − ${both}`;break}
case 11:prompt=L(`ある数を${a}倍して${b}を足すと${a*n+b}。元の数は？`,`Multiply a number by ${a}, then add ${b}, giving ${a*n+b}. Original number?`,`Un nombre × ${a}, puis + ${b}, donne ${a*n+b}. Nombre initial ?`);num(n);explain=L('足した数を引いて、倍率で割ります。','Subtract first, then divide.','Soustrayez puis divisez.');break;
case 12:{const d=ri(r,3,8),q=ri(r,3,9),rem=ri(r,0,d-1);prompt=L(`${d*q+rem}を${d}で割った余りは？`,`Remainder of ${d*q+rem} divided by ${d}?`,`Reste de ${d*q+rem} divisé par ${d} ?`);correct=String(rem);wrong=shuffle(Array.from({length:d},(_,i)=>String(i)).filter(x=>x!==correct),r).slice(0,3);while(wrong.length<3)wrong.push(String(d+wrong.length));explain=`${d*q+rem} = ${d} × ${q} + ${rem}`;break}
case 13:{const x=ri(r,4,15);prompt=L('二進数を十進数にすると？','Convert binary to decimal:','Convertissez en décimal :')+'\n'+x.toString(2);num(x);explain=L('右から１、２、４、８の位です。','Place values from right: 1, 2, 4, 8.','De droite : 1, 2, 4, 8.');break}
case 14:{const x=ri(r,1,3),y=ri(r,1,3);prompt=L(`右に${x}回、下に${y}回だけ進む最短経路は何通り？`,`Shortest paths with ${x} right and ${y} down moves?`,`Combien de trajets avec ${x} pas à droite et ${y} vers le bas ?`);num(choose(x+y,x));explain=L('移動順序の組み合わせを数えます。','Choose positions for the right moves.','Choisissez les positions des pas à droite.');break}
case 15:prompt=L('「全員が赤い帽子をかぶっている」の否定は？','Negate: “Everyone wears a red hat.”','Niez : « Tout le monde porte un chapeau rouge. »');correct=L('赤い帽子でない人が少なくとも１人いる','At least one person does not wear a red hat','Au moins une personne ne porte pas de chapeau rouge');wrong=[L('誰も赤い帽子をかぶっていない','Nobody wears a red hat','Personne ne porte de chapeau rouge'),L('全員が青い帽子をかぶっている','Everyone wears a blue hat','Tous portent un chapeau bleu'),L('赤い帽子の人が１人だけいる','Exactly one person wears a red hat','Une seule personne porte un chapeau rouge')];explain=L('「全員」の否定は「少なくとも１人は違う」です。','Negating “all” requires at least one exception.','Nier « tous » exige au moins une exception.');break;
case 16:{const k=ri(r,0,15),s=[0,2,4,6].map(i=>String.fromCharCode(65+k+i));prompt=L('次の文字は？','Next letter?','Lettre suivante ?')+'\n'+s.slice(0,3).join(' · ')+' · ?';correct=s[3];wrong=[1,3,5].map(i=>String.fromCharCode(65+k+i));explain=L('アルファベットを１文字おきに進みます。','Advance two alphabet positions.','Avancez de deux lettres.');break}
case 17:{const x=ri(r,11,19);prompt=`${x} × 99 = ?`;num(x*99,[-100,-10,10,100]);explain=`${x} × (100 − 1) = ${x*100} − ${x}`;break}
case 18:prompt=L('３箱に「リンゴ」「ミカン」「両方」のラベル。ラベルは全部間違い。中身を確定するため、まず１個取り出す箱は？','Three boxes labelled Apples, Oranges, Mixed. All labels are wrong. Which box should you sample first?','Boîtes étiquetées Pommes, Oranges, Mélange. Toutes les étiquettes sont fausses. Où tirer un fruit ?');correct=L('「両方」の箱','Mixed-labelled box','Boîte « Mélange »');wrong=[L('「リンゴ」の箱','Apples-labelled box','Boîte « Pommes »'),L('「ミカン」の箱','Oranges-labelled box','Boîte « Oranges »'),L('どの箱でも必ず確定できる','Any box always suffices','N’importe laquelle suffit toujours')];explain=L('「両方」は間違いなので単一の果物。１個で中身が確定し、残りも決まります。','The Mixed-labelled box contains only one kind, so one fruit identifies it and resolves the rest.','La boîte « Mélange » est d’un seul type. Un fruit la révèle, puis les autres.');break;
case 19:{const k=ri(r,3,5);prompt=L(`異なる${k}冊を一列に並べる方法は？`,`Ways to arrange ${k} distinct books in a row?`,`Façons d’aligner ${k} livres différents ?`);let v=1;for(let i=2;i<=k;i++)v*=i;num(v,[-6,-2,2,6]);explain=Array.from({length:k},(_,i)=>k-i).join(' × ');break}
case 20:{const x=a*n,y=b*n;prompt=L('最大公約数は？','Greatest common divisor?','Plus grand diviseur commun ?')+`\n${x}, ${y}`;num(gcd(x,y));explain=L('両方を割り切る最大の整数です。','The largest integer dividing both.','Le plus grand entier divisant les deux.');break}
case 21:{const face=ri(r,1,6);prompt=L(`向かい合う面の合計が７のサイコロ。「${face}」の裏は？`,`A die has opposite faces summing to 7. Opposite of ${face}?`,`Les faces opposées totalisent 7. Opposé de ${face} ?`);num(7-face,[-2,-1,1,2]);explain=`7 − ${face} = ${7-face}`;break}
case 22:{const sets=[['APPLE','PEAR','PLUM','CHAIR'],['RED','BLUE','GREEN','SPOON'],['CAT','DOG','FOX','TABLE']],set=sets[ri(r,0,2)];prompt=L('英単語：仲間外れは？','Which word is the odd one out?','Quel mot est l’intrus ?');correct=set[3];wrong=set.slice(0,3);explain=L('他の３語は同じ分類です。','The other three belong to one category.','Les trois autres appartiennent à la même catégorie.');break}
case 23:prompt=L('宝はA・B・Cの１箱。札は「A：宝はA」「B：宝はAではない」「C：宝はBではない」。真実は１枚だけ。宝は？','Treasure is in A, B or C. Signs: A says “in A”; B says “not in A”; C says “not in B”. Exactly one sign is true. Where?','Trésor dans A, B ou C. A dit « dans A », B « pas dans A », C « pas dans B ». Une seule affirmation vraie. Où ?');correct='B';wrong=['A','C',L('決められない','Undetermined','Indéterminé')];explain=L('AとBの札は必ず片方だけ真実。Cは偽なので、宝はBです。','Exactly one of A and B is true. C must be false, so treasure is in B.','A et B sont contradictoires. C doit être faux : trésor dans B.');break;
}
wrong=[...new Set(wrong.map(String))].filter(v=>v!==String(correct));while(wrong.length<3)wrong.push(String(Number(correct)+wrong.length+11));return{prompt,correct:String(correct),wrong:wrong.slice(0,3),explain}}
function gamesView(){return title('games')+`<p>${L('一勝負は１分程度。時間制限なし、途中で閉じても大丈夫。速度系は１つだけです。','About a minute per round. No time limit; leave any time. Only one speed-focused game.','Environ une minute par manche. Sans limite. Un seul jeu axé sur la vitesse.')}</p><div class="grid">${GAME_NAMES.map((n,i)=>`<button class="tile" data-action="game:${i}" data-help="games"><span class="icon">${i<24?'◇':'♟'}</span><span><small>${String(i+1).padStart(2,'0')}</small><strong>${L(...n)}</strong></span></button>`).join('')}</div>`}
function startGame(id){gameState={id,start:Date.now(),done:false};let html=`<h1>${L(...GAME_NAMES[id])}</h1>`;if(id<24){const q=questionGame(id),answers=shuffle([q.correct,...q.wrong]);Object.assign(gameState,{q,answers});html+=`<div class="game-board">${esc(q.prompt)}</div><div class="answers">${answers.map((a,i)=>btn(esc(a),'gameAnswer:'+i)).join('')}</div>`}else{html+=`<p id="boardNote"></p><div id="board" class="board"></div>`}html+=`<p id="gameResult" role="status"></p><div class="row">${btn(t('close'),'cancel')}${btn(L('もう一勝負','Play again','Rejouer'),'game:'+id)}</div>`;modal(html);if(id>=24)initBoard(id)}
function gameAnswer(i){if(gameState.done)return;gameState.done=true;const ok=gameState.answers[i]===gameState.q.correct;$('gameResult').innerHTML=`<strong class="${ok?'success':'error'}">${ok?t('correct'):t('incorrect')}</strong><p>${L('答え','Answer','Réponse')}：${esc(gameState.q.correct)}</p><p>${esc(gameState.q.explain)}</p>`}
function winBoard(){gameState.done=true;$('gameResult').innerHTML=`<strong class="success">${L('できました！','Solved!','Réussi !')}</strong> ${Math.round((Date.now()-gameState.start)/1000)} ${L('秒','seconds','secondes')}`}
function initBoard(id){const g=gameState;if(id===24){g.cards=shuffle(['🌷','🌷','⭐','⭐','🌙','🌙','🍀','🍀']);g.open=[];g.matched=[];$('boardNote').textContent=L('同じ絵を２枚ずつ見つけます。','Find matching pairs.','Retrouvez les paires.')}if(id===25){g.lights=Array(9).fill(false);for(const i of [0,2,4,7])toggleLight(i);$('boardNote').textContent=L('押した場所と上下左右が反転。全部消してください。','A tap toggles itself and neighbours. Turn all off.','Un appui inverse la case et ses voisines. Éteignez tout.')}if(id===26){g.tiles=[1,2,3,4,5,6,7,8,0];let blank=8,prev=-1;for(let j=0;j<12;j++){const choices=[blank-3,blank+3,blank%3?blank-1:-1,blank%3<2?blank+1:-1].filter(x=>x>=0&&x<9&&x!==prev);const n=choices[Math.floor(Math.random()*choices.length)];[g.tiles[n],g.tiles[blank]]=[g.tiles[blank],g.tiles[n]];prev=blank;blank=n}if(g.tiles.every((v,i)=>v===(i+1)%9)){[g.tiles[8],g.tiles[7]]=[g.tiles[7],g.tiles[8]]}$('boardNote').textContent=L('空白の隣を押し、１〜８を順番に。','Tap next to the blank to arrange 1–8.','Touchez près du vide pour ranger 1 à 8.')}if(id===27){g.stones=9;g.turn=true;$('boardNote').textContent=L('１〜３個取れます。最後の石を取った方の勝ち。あなたが先手です。','Take 1–3. Last stone wins. You go first.','Prenez 1 à 3 pierres. La dernière gagne. Vous commencez.')}if(id===28){g.order=shuffle([1,2,3,4,5,6,7,8,9]);g.next=1;$('boardNote').textContent=L('１から９まで順に押してください。','Tap 1 through 9 in order.','Touchez de 1 à 9 dans l’ordre.')}if(id===29){g.pos=0;g.walls=[2,7,10,14,17,22];$('boardNote').textContent=L('矢印で★まで進みます。黒いマスは壁。','Use arrows to reach ★. Black squares are walls.','Avec les flèches, atteignez ★. Cases noires : murs.')}paintBoard()}
function toggleLight(i){for(const n of [i,i-3,i+3,i%3?i-1:-1,i%3<2?i+1:-1])if(n>=0&&n<9)gameState.lights[n]=!gameState.lights[n]}
function paintBoard(){const g=gameState,b=$('board');b.style.gridTemplateColumns=`repeat(${g.id===24?4:g.id===29?5:3},1fr)`;if(g.id===24)b.innerHTML=g.cards.map((v,i)=>btn(g.open.includes(i)||g.matched.includes(i)?v:'?',`cell:${i}`)).join('');if(g.id===25)b.innerHTML=g.lights.map((v,i)=>btn(v?'💡':'·',`cell:${i}`,v?'primary':'')).join('');if(g.id===26)b.innerHTML=g.tiles.map((v,i)=>btn(v||'　',`cell:${i}`)).join('');if(g.id===27){b.style.display='block';b.innerHTML=`<p class="game-board">${'● '.repeat(g.stones)}</p><div class="row">${[1,2,3].map(n=>`<button data-action="cell:${n}" ${n>g.stones?'disabled':''}>−${n}</button>`).join('')}</div>`}if(g.id===28)b.innerHTML=g.order.map((v,i)=>btn(v<g.next?'✓':String(v),`cell:${i}`,v<g.next?'primary':'')).join('');if(g.id===29)b.innerHTML=Array.from({length:25},(_,i)=>`<div style="height:38px;text-align:center;background:${g.walls.includes(i)?'#514653':'var(--bg)'}">${g.pos===i?'●':i===24?'★':''}</div>`).join('')+`<div style="grid-column:1/-1" class="row">${btn('←','cell:left')}${btn('↑','cell:up')}${btn('↓','cell:down')}${btn('→','cell:right')}</div>`}
function cellAction(raw){const g=gameState;if(!g||g.done||g.busy)return;const i=Number(raw);if(g.id===24){if(g.open.includes(i)||g.matched.includes(i))return;g.open.push(i);if(g.open.length===2){if(g.cards[g.open[0]]===g.cards[g.open[1]]){g.matched.push(...g.open);g.open=[];if(g.matched.length===8)winBoard()}else{g.busy=true;setTimeout(()=>{if(gameState!==g)return;g.open=[];g.busy=false;if($('board'))paintBoard()},700)}}}if(g.id===25){toggleLight(i);if(g.lights.every(x=>!x))winBoard()}if(g.id===26){const z=g.tiles.indexOf(0);if(Math.abs(Math.floor(z/3)-Math.floor(i/3))+Math.abs(z%3-i%3)===1)[g.tiles[z],g.tiles[i]]=[g.tiles[i],g.tiles[z]];if(g.tiles.every((v,i)=>v===(i+1)%9))winBoard()}if(g.id===27){if(i<1||i>3||i>g.stones)return;g.stones-=i;if(g.stones===0)winBoard();else{const take=g.stones%4||Math.min(1,g.stones);g.stones-=take;if(g.stones===0){g.done=true;$('gameResult').textContent=L('相手の勝ち。４個をひとまとまりに考えてみましょう。','Computer wins. Think in groups of four.','L’ordinateur gagne. Pensez par groupes de quatre.')}else $('gameResult').textContent=L(`相手は${take}個取りました。`,`Computer took ${take}.`,`L’ordinateur a pris ${take}.`)}}if(g.id===28){if(g.order[i]===g.next)g.next++;if(g.next===10)winBoard()}if(g.id===29){const p=g.pos;let n=p;if(raw==='left'&&p%5)n=p-1;if(raw==='right'&&p%5<4)n=p+1;if(raw==='up'&&p>=5)n=p-5;if(raw==='down'&&p<20)n=p+5;if(!g.walls.includes(n))g.pos=n;if(g.pos===24)winBoard()}paintBoard()}
// Rows: upper trigram; columns: lower trigram. Order: Heaven, Lake, Fire, Thunder, Wind, Water, Mountain, Earth.
const HEX_TABLE=[[1,10,13,25,44,6,33,12],[43,58,49,17,28,47,31,45],[14,38,30,21,50,64,56,35],[34,54,55,51,32,40,62,16],[9,61,37,42,57,59,53,20],[5,60,63,3,48,29,39,8],[26,41,22,27,18,4,52,23],[11,19,36,24,46,7,15,2]];
const HEX_NAMES=['乾','坤','屯','蒙','需','訟','師','比','小畜','履','泰','否','同人','大有','謙','豫','隨','蠱','臨','觀','噬嗑','賁','剝','復','無妄','大畜','頤','大過','坎','離','咸','恆','遯','大壯','晉','明夷','家人','睽','蹇','解','損','益','夬','姤','萃','升','困','井','革','鼎','震','艮','漸','歸妹','豐','旅','巽','兌','渙','節','中孚','小過','既濟','未濟'];
const TRIGRAMS=[{bits:'111',names:['天','Heaven','Ciel'],idea:['小さく始める力を大切に。今日は、自分で選べることを一つ選んでみましょう。','Value a small beginning. Choose one thing within your control today.','Un petit début compte. Choisissez une chose à votre portée.']},{bits:'110',names:['沢','Lake','Lac'],idea:['楽しみを味わう時間を。好きな言葉や音に、少し触れてみましょう。','Make room for enjoyment. Spend a moment with words or sounds you like.','Accordez une place au plaisir : des mots ou sons aimés.']},{bits:'101',names:['火','Fire','Feu'],idea:['一つのことを丁寧に見る日。気づいたことを一言残してみましょう。','Look carefully at one thing. Write down a small observation.','Observez une chose avec soin. Notez une petite découverte.']},{bits:'100',names:['雷','Thunder','Tonnerre'],idea:['変化に驚いたら、ひと呼吸。すぐ答えを出さず、間を置いてもよい日です。','When surprised by change, pause. An immediate answer is not required.','Face au changement, faites une pause. La réponse peut attendre.']},{bits:'011',names:['風','Wind','Vent'],idea:['少しずつ整えるイメージ。身の回りの一か所を心地よくしてみましょう。','Think of gentle adjustments. Make one small place more comfortable.','Ajustez doucement : rendez un petit endroit plus agréable.']},{bits:'010',names:['水','Water','Eau'],idea:['無理に押し進めず、進める道を探すイメージ。手間を一つ減らしてみましょう。','Find a workable path rather than forcing things. Remove one unnecessary task.','Cherchez une voie souple. Épargnez-vous une tâche inutile.']},{bits:'001',names:['山','Mountain','Montagne'],idea:['立ち止まる時間も大切に。今日は何をしないか選んでみましょう。','Stillness has value. Choose something you can leave undone today.','Le repos a sa valeur. Choisissez ce qui peut attendre.']},{bits:'000',names:['地','Earth','Terre'],idea:['受け止める余白を。助けや親切を受け取ってもよい日です。','Leave room to receive. You may accept kindness and help.','Laissez une place à l’accueil. Acceptez une aide ou une attention.']}];
function hexFromLines(lines){const bits=lines.map(n=>n%2?'1':'0').join(''),lower=TRIGRAMS.findIndex(t=>t.bits===bits.slice(0,3)),upper=TRIGRAMS.findIndex(t=>t.bits===bits.slice(3));return{n:HEX_TABLE[upper][lower],upper,lower}}
async function drawFortune(){const today=day();if(S.fortune[today])return;const r=new Uint32Array(18);crypto.getRandomValues(r);const lines=Array.from({length:6},(_,i)=>r.slice(i*3,i*3+3).reduce((sum,x)=>sum+(x%2?3:2),0));await mutate(n=>n.fortune[today]={lines,created:localDT()},{undo:false})}
function fortuneView(){const f=S.fortune[day()];return title('fortune')+`<section class="card"><p>${L('伝統的な三枚のコイン法を端末内で再現します。同じ日は同じ結果です。未来や病状を予測するものではありません。','Simulates the traditional three-coin method on your device. Same result all day. It does not predict the future or health outcomes.','Simulation de la méthode traditionnelle des trois pièces. Même résultat toute la journée. Aucune prédiction médicale ou de l’avenir.')}</p>${f?fortuneResult(f):btn(L('今日の一卦を開く','Reveal today’s hexagram','Découvrir l’hexagramme du jour'),'drawFortune','primary')}</section>`}
function fortuneResult(f){const h=hexFromLines(f.lines),u=TRIGRAMS[h.upper],lo=TRIGRAMS[h.lower],changed=f.lines.map(n=>n===6?7:n===9?8:n),c=hexFromLines(changed);return `<div style="text-align:center"><span class="chip">${day()}</span><h2>${h.n}　${HEX_NAMES[h.n-1]}</h2><div style="font:38px/1.15 monospace;letter-spacing:5px">${f.lines.slice().reverse().map(n=>n%2?'━━━━━':'━━ ━━').join('<br>')}</div><p>${L('上','Upper','Haut')}：${L(...u.names)} ／ ${L('下','Lower','Bas')}：${L(...lo.names)}</p>${f.lines.some(n=>n===6||n===9)?`<p>${L('変化する線を反転した卦','Hexagram after changing lines','Hexagramme après mutation')}：${c.n} ${HEX_NAMES[c.n-1]}</p>`:''}</div><h2>${L('象徴から考えるヒント（独自の解釈）','Reflection inspired by the symbol (our interpretation)','Piste de réflexion (interprétation originale)')}</h2><p>${L(...u.idea)}</p><small>${L('卦名・構成は『周易』の伝統に基づきます。上の文章は古典の引用や逐語訳ではありません。','Names and structure follow the Zhou Yi tradition. The reflection above is not a quotation or literal translation.','Noms et structure issus du Zhou Yi. Le texte ci-dessus n’est pas une citation ni une traduction littérale.')}</small><div style="margin-top:14px">${btn(L('日記に残す','Save to journal','Noter dans le journal'),'fortuneSave')}</div>`}
const HELP={
home:()=>[L('表紙から使いたい機能を選びます。','Choose a feature on the home screen.','Choisissez une fonction depuis l’accueil.'),L('上部の⌂で戻ります。入力中は保存またはキャンセルしてから戻ってください。','Use ⌂ to return. Save or cancel open forms first.','Utilisez ⌂ pour revenir. Enregistrez ou annulez les formulaires ouverts.')],
help:()=>[L('説明モード中は３秒長押しで説明を開きます。通常の発信や編集は動きません。','In help mode, hold 3 seconds for instructions. Calls and editing are disabled.','En mode aide, appuyez 3 secondes. Appels et modifications sont désactivés.'),L('上部の ? をもう一度押すと通常モードへ戻ります。','Tap ? again for normal mode.','Touchez ? pour revenir au mode normal.')],
diary:()=>[L('白紙の日記帳です。「新しく記録」から日時・文章・写真を保存できます。','A free journal. Use New record for text, dates and photos.','Journal libre : nouvelle note pour texte, date et photos.'),L('気分・便通は任意です。写真は長辺1600px以内へ縮小されます。本文は検索できます。','Mood and bowel entries are optional. Photos are resized to 1600px. Text is searchable.','Humeur et transit facultatifs. Photos réduites à 1600 px. Texte recherchable.')],
vitals:()=>[L('測定した項目にチェックを入れ、ダイヤルで値を選び保存します。','Tick measured items, choose values with dials, then save.','Cochez les mesures effectuées, choisissez les valeurs, enregistrez.'),L('未測定はチェックしません。血糖の食前・食後も選びます。グラフは項目と期間を切り替えて表示します。','Leave unmeasured items unticked. Select glucose context. Change metric and period for charts.','Ne cochez pas les mesures absentes. Choisissez le contexte glycémique, puis la période du graphique.')],
women:()=>[L('出血、おりもの、痛み、排尿、むくみ、ほてり、月経の変化を任意で記録します。','Optionally record bleeding, discharge, pain, urination, swelling, hot flushes and periods.','Notez saignements, pertes, douleurs, mictions, gonflements, bouffées et règles.'),L('「項目を選ぶ」で不要な項目を隠せます。診断機能ではありません。気になる症状は病院へ相談してください。','Hide unused fields with Choose fields. This is not a diagnostic tool. Contact your care team for concerns.','Masquez les champs inutiles. Ce n’est pas un diagnostic. Contactez l’équipe médicale en cas de souci.')],
meds:()=>[L('処方の内容を確認し、薬名・量・時刻を登録します。服用後に「服用済み」を押します。','Copy the prescription: name, dose and times. Tap Taken after a dose.','Recopiez l’ordonnance : nom, dose, horaires. Touchez Pris après la prise.'),L('飲んだか不明の場合も記録できます。追加服用や量の変更をアプリで判断しません。','You can log uncertainty. The app does not decide extra doses or dose changes.','Vous pouvez noter un doute. L’application ne décide ni dose supplémentaire ni modification.')],
plans:()=>[L('時刻と文章、または録音を登録します。録音は最長20秒です。','Set a time and text or a recording (max 20 seconds).','Choisissez heure et texte ou enregistrement (20 secondes maximum).'),L('この予定画面が開いている間だけ音声通知します。スマホのロック中には頼れません。','Voice alerts only while the plans page is active. Do not rely on them while locked.','Rappels uniquement quand cette page est active. Pas de fiabilité écran verrouillé.')],
phone:()=>[L('30件登録できます。名前部分を２秒長押しして名前と番号を入力します。','30 contacts. Hold a name 2 seconds to edit name and number.','30 contacts. Appui de 2 secondes pour saisir nom et numéro.'),L('横にスライドすると発信確認へ進みます。iPhoneの確認後に電話がかかります。','Slide to start the call confirmation. iPhone asks before dialling.','Glissez puis confirmez l’appel sur iPhone.')],
owner:()=>[L('顔写真・氏名・住所・電話・病院情報を登録できます。２秒長押し、または編集ボタンを使います。','Register photo, name, address, phone and hospital. Hold 2 seconds or tap Edit.','Saisissez photo, identité, adresse et hôpital. Appui de 2 s ou Modifier.'),L('表示は任意です。ロック画面からは確認できず、緊急時に見てもらえる保証はありません。','Display is optional. Not available on the lock screen; emergency access is not guaranteed.','Affichage facultatif. Non visible écran verrouillé, sans garantie en urgence.')],
mirror:()=>[L('通常時、ロゴ１秒長押しで内カメラの鏡になります。','Normally hold logo 1 second to open the front camera mirror.','Appui de 1 seconde sur le logo pour le miroir.'),L('カメラ許可が必要です。鏡２秒長押し、または閉じるで戻りカメラを停止します。撮影・送信はしません。','Camera permission required. Hold mirror 2 seconds or Close to stop. No photos or uploads.','Autorisation caméra nécessaire. Appui de 2 s ou Fermer pour arrêter. Ni photo ni envoi.')],
frame:()=>[L('写真を３枚まで選び、写真立てを開きます。左右スワイプで切り替わります。','Choose up to 3 photos. Open the frame and swipe left or right.','Choisissez jusqu’à 3 photos et glissez pour les changer.'),L('タップで操作ボタンを表示・非表示。戻るで表紙へ。写真はバックアップに含まれます。','Tap to show/hide controls. Back closes the frame. Photos are included in backups.','Touchez pour afficher les commandes. Retour ferme le cadre. Photos incluses dans la sauvegarde.')],
quiz:()=>[L('バラバラの英単語から意味を推理し、日本語５択から選びます。','Infer meaning from shuffled English words; choose among 5 Japanese answers.','Déduisez le sens, puis choisissez parmi 5 réponses japonaises.'),L('日替わりの１問と、別の問題で遊べます。100問を収録。ヒントは英文の前半を表示します。','Daily question plus extra rounds. 100 questions. Hint shows the first half in order.','Question quotidienne et autres manches. 100 questions. Indice : première moitié en ordre.')],
games:()=>[L('考える遊びを中心に30個。ゲームを選び、答えや盤面を押して遊びます。','30 games, mostly reasoning. Choose a game and use answers or board buttons.','30 jeux, surtout de réflexion. Choisissez et jouez.'),L('１分程度が目安ですが強制終了しません。いつでも閉じられます。','About 1 minute, no forced time limit. Close at any time.','Environ 1 minute, sans limite imposée. Fermez à tout moment.')],
fortune:()=>[L('三枚コイン法で６本の線を作り、卦を表示。同じ日は同じ結果を記録します。','Six lines from the three-coin method form a hexagram. Same result for the day.','Six lignes par la méthode des trois pièces. Même résultat du jour.'),L('古典の構成に沿った娯楽です。解釈文は独自制作で、未来・治療結果を予測しません。','Traditional structure, original reflection for recreation. No prediction of the future or treatment.','Structure traditionnelle, réflexion originale pour le loisir. Aucune prédiction médicale.')],
backup:()=>[L('記録・写真・設定・ごみ箱をJSONファイルへ書き出します。別の端末などにも保管してください。','Export records, photos, settings and trash to JSON. Keep a copy on another device.','Export JSON des notes, photos, réglages et corbeille. Gardez une copie ailleurs.'),L('新端末でファイルを読み込むと移行できます。現在のデータを置き換えるため、先に書き出してください。暗号化されていません。','Import to transfer phones. Import replaces current data: export first. Files are not encrypted.','Importez pour changer d’appareil. L’import remplace les données : exportez avant. Fichier non chiffré.')],
trash:()=>[L('削除した記録・薬・予定はここに残ります。「元に戻す」で復元できます。','Deleted records, medications and plans stay here. Restore brings them back.','Notes, médicaments et agendas supprimés restent ici. Restaurer les récupère.'),L('完全削除は元に戻せません。時点復元はありません。写真の差し替えや編集は直後の取り消しで戻せます。','Permanent deletion cannot be undone. No point-in-time restore. Undo last save can revert an edit or photo replacement.','Suppression définitive irréversible. Pas de restauration historique. Annuler peut rétablir une modification récente.')],
calendar:()=>[L('月を選ぶと写真カレンダーを表示。日付からその日の記録を開きます。','Select a month; tap a day to see its records.','Choisissez un mois puis un jour pour ses notes.'),L('年表はアプリ内の記録を時系列で並べます。他の日記アプリとは自動連携しません。','Timeline lists this app’s records. No automatic link to other diary apps.','Chronologie des données de cette application, sans lien automatique à d’autres journaux.')],
search:()=>[L('見出し・本文・備考・写真の名前などを部分一致検索。期間も指定できます。','Search titles, notes and photo names by substring, with optional date range.','Recherche partielle des titres, notes et noms de photos avec dates facultatives.'),L('写真内の文字を読む機能はありません。最新100件を表示し、期間で絞れます。','No text recognition inside photos. Shows latest 100 matches; narrow with dates.','Pas de reconnaissance de texte dans les photos. 100 résultats récents, affinables par dates.')],
settings:()=>[L('暗い画面、大きな文字、表紙の項目を選び保存します。言語は上部から変更します。','Choose dark mode, larger text and home sections. Change language above.','Choisissez thème, taille et rubriques. Langue en haut.'),L('項目を隠しても記録は消えません。本人が書いた文章は自動翻訳しません。','Hiding sections does not delete data. User text is not auto-translated.','Masquer ne supprime rien. Les textes personnels ne sont pas traduits.')],
night:()=>[L('大きな時計と端末内で合成した雨音。音量は端末で調整してください。','Large clock and synthesized rain. Adjust device volume.','Grande horloge et pluie synthétique. Réglez le volume sur l’appareil.'),L('画面を離れると雨音は停止します。タイマーや医療機器ではありません。','Rain stops when you leave this screen. Not a medical device or alarm.','La pluie s’arrête en quittant l’écran. Ni dispositif médical ni alarme.')]
};
function showHelp(key){if(key==='photo')key='diary';if(!HELP[key])key=$('modal').open&&$('entryForm')?$('entryForm').dataset.help:(page in HELP?page:'home');const lines=HELP[key]();const el=document.createElement('div');el.className='overlay help-page';el.innerHTML=`<div class="inner"><span class="chip">${t('help')}</span><h1>${I[key]?t(key):L('手鏡','Mirror','Miroir')}</h1>${lines.map(p=>`<p>${esc(p)}</p>`).join('')}${btn(t('close'),'helpClose','primary')}</div>`;($('modal').open?$('modal'):document.body).append(el)}
function afterRender(){if(page==='vitals'){$('range').onchange=e=>{range=Number(e.target.value);render()};if($('glucoseFilter'))$('glucoseFilter').onchange=e=>{glucoseFilter=e.target.value;render()}}if(page==='calendar')$('calendarMonth').onchange=e=>{if(e.target.value){calendarMonth=e.target.value;render()}};if(page==='backup'){$('importFile').onchange=e=>{if(e.target.files[0])importBackup(e.target.files[0])};storageInfo()}if(page==='frame')document.querySelectorAll('[data-frame]').forEach(input=>input.onchange=async e=>{if(!e.target.files[0])return;input.disabled=true;try{const data=await imageData(e.target.files[0]),i=Number(input.dataset.frame);await mutate(n=>{while(n.frames.length<i)n.frames.push(null);n.frames[i]=data})}catch(err){toast(err.message)}finally{input.disabled=false}});if(page==='home')$('ownerVisible').onchange=async e=>{await mutate(n=>n.settings.ownerVisible=e.target.checked,{undo:false})};if(page==='night')afterRender.clock=setInterval(()=>{if(page!=='night'){clearInterval(afterRender.clock);return}if($('clock'))$('clock').textContent=new Date().toLocaleTimeString()},1000)}
async function storageInfo(){const el=$('storageInfo');if(!el)return;try{const e=await navigator.storage.estimate();el.textContent=`${L('使用量','Used','Utilisé')}：${(e.usage/1048576).toFixed(1)} MB / ${L('割当の目安','Estimated quota','Quota estimé')}：${(e.quota/1048576).toFixed(0)} MB`}catch{el.textContent=L('容量情報を取得できません','Storage information unavailable','Stockage non disponible')}}
let hold=null,swallowUntil=0;
document.addEventListener('contextmenu',e=>{if(helpMode||e.target.closest('[data-hold],.slider'))e.preventDefault()});
document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const target=e.target.closest('[data-hold]'),slider=e.target.closest('.handle')?.closest('.slider');const helpSwitch=e.target.closest('#helpBtn,[data-action="toggleHelp"]');if(e.target.closest('.help-page,#lang,[data-action="cancel"],[data-action="goTop"],#homeBtn'))return;const ms=helpSwitch?3000:helpMode?3000:target?.dataset.hold==='mirror'?1000:target?2000:0;if(!ms)return;hold={startX:e.clientX,startY:e.clientY,target,help:helpMode||!!helpSwitch,key:helpSwitch?'help':e.target.closest('[data-help]')?.dataset.help||($('entryForm')?.dataset.help||page),slider,dragging:false};const h=hold;$('progress').style.transition='none';$('progress').style.width='0';requestAnimationFrame(()=>{$('progress').style.transition=`width ${ms}ms linear`;$('progress').style.width='100%'});h.timer=setTimeout(()=>{if(hold!==h)return;swallowUntil=Date.now()+600;resetProgress();if(h.help)showHelp(h.key);else runHold(h.target.dataset.hold);hold=null},ms)});
function resetProgress(){$('progress').style.transition='none';$('progress').style.width='0'}
document.addEventListener('pointermove',e=>{if(!hold)return;const dx=e.clientX-hold.startX,dy=e.clientY-hold.startY;if(Math.abs(dx)>10||Math.abs(dy)>10){clearTimeout(hold.timer);resetProgress();if(hold.slider&&!hold.help&&Math.abs(dx)>Math.abs(dy)&&dx>0){hold.dragging=true;const max=hold.slider.clientWidth-hold.target.clientWidth-10;hold.target.style.transform=`translateX(${Math.min(dx,max)}px)`;if(e.cancelable)e.preventDefault()}else{if(hold.target)hold.target.style.transform='';hold=null}}},{passive:false});
document.addEventListener('pointerup',e=>{if(!hold)return;const h=hold;clearTimeout(h.timer);resetProgress();if(h.slider&&h.dragging){const max=h.slider.clientWidth-h.target.clientWidth-10,dx=e.clientX-h.startX;h.target.style.transform='';swallowUntil=Date.now()+600;if(dx>=max*.8){const c=S.contacts[Number(h.slider.dataset.contact)];if(c.number){const number=c.number.replace(/[^+0-9*#]/g,'');if(number)window.location.href='tel:'+number}else toast(t('unregistered'))}}hold=null});
document.addEventListener('pointercancel',()=>{if(hold){clearTimeout(hold.timer);if(hold.target)hold.target.style.transform='';hold=null}resetProgress()});
function runHold(a){if(a==='mirror')mirror();else if(a==='mirrorClose'){closeOverlay()}else if(a==='owner')ownerEdit();else if(a.startsWith('contact:'))contactEdit(Number(a.split(':')[1]))}
function closeOverlay(){if(overlayCleanup){overlayCleanup();overlayCleanup=null}document.querySelector('.overlay:not(.help-page)')?.remove()}
$('homeBtn').onclick=goTop;$('helpBtn').onclick=()=>{if(Date.now()<swallowUntil)return;setHelpMode(!helpMode)};$('lang').onchange=async e=>{lang=e.target.value;await mutate(n=>n.settings.lang=lang,{undo:false})};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action,parts=a.split(':'),[action,arg,arg2]=parts;if(action==='toggleHelp'){if(Date.now()<swallowUntil)return;setHelpMode(!helpMode);return}if(action==='helpClose'){b.closest('.help-page').remove();return}if(Date.now()<swallowUntil)return;if(helpMode&&!['cancel','overlayClose','goTop'].includes(action)){toast(L('３秒長押しで説明を表示します','Hold 3 seconds for help','Appuyez 3 secondes pour l’aide'));return}try{switch(action){case 'goTop':goTop();break;case 'nav':stopNoise();nav(arg);break;case 'new':newEntry(arg);break;case 'edit':{const entry=S.entries.find(x=>x.id===arg);newEntry(entry.kind,arg);break}case 'commit':await commitEntry(arg);break;case 'cancel':closeModal();break;case 'step':{const s=$('v-'+arg),next=Math.max(0,Math.min(s.options.length-1,s.selectedIndex+Number(arg2)));s.selectedIndex=next;$('on-'+arg).checked=true;break}case 'removePhoto':editPhotos.splice(Number(arg),1);showEditPhotos();break;case 'undo':await undo();break;case 'trash':if(confirm(L('この記録をごみ箱へ移しますか？','Move this record to trash?','Mettre cette note à la corbeille ?')))await mutate(n=>n.entries.find(x=>x.id===arg).deleted=Date.now());break;case 'photo':{const en=S.entries.find(x=>x.id===arg);showPhotos(en.photos.map(p=>p.data),Number(arg2));break}case 'metric':metric=arg;render();break;case 'womenSettings':womenSettings();break;case 'saveWomenSettings':{const hidden=W.filter(w=>!$('show-'+w[0]).checked).map(w=>w[0]);if(await mutate(n=>n.settings.hiddenWomen=hidden,{undo:false}))closeModal();break}case 'medEdit':medEdit(arg);break;case 'medSave':{const m={id:arg==='new'?uid():arg,name:$('medName').value.trim(),dose:medicineDoseFromForm(),amount:$('medDoseNumber').value,unit:$('medUnit').value,strength:$('medStrength').value,times:$('medTimes').value,infoUrl:$('medInfoUrl').value.trim(),note:$('medNote').value,remaining:$('medRemaining').value===''?'':Number($('medRemaining').value)};if(m.amount!==''&&(!Number.isFinite(Number(m.amount))||Number(m.amount)<=0)){toast(L('服用量は正の数字で入力してください','Enter a positive dose','Saisissez une quantité positive'));break}if(m.infoUrl&&!officialMedicineUrl(m.infoUrl)){toast(L('情報URLはPMDAのHTTPSページを指定してください','Use a PMDA HTTPS URL','Utilisez une URL HTTPS de PMDA'));break}if(!m.name){toast(L('薬名を入力してください','Enter medication name','Saisissez le médicament'));break}if(await mutate(n=>{const i=n.medications.findIndex(x=>x.id===m.id);if(i>=0)n.medications[i]=m;else n.medications.push(m)}))closeModal();break}case 'medTrash':if(confirm(L('ごみ箱へ移しますか？','Move to trash?','Mettre à la corbeille ?')))await mutate(n=>n.medications.find(x=>x.id===arg).deleted=Date.now());break;case 'dose':await recordDose(arg,arg2);break;case 'planEdit':planEdit(arg);break;case 'planSave':{if(recording||recordProcessing){toast(L('先に録音を停止してください','Stop recording first','Arrêtez l’enregistrement'));break}const p={id:arg==='new'?uid():arg,title:$('planTitle').value.trim(),date:$('planDate').value,time:$('planTime').value,repeat:$('planRepeat').value,sound:pendingSound,enabled:true};if(!p.title||!p.time||!p.date){toast(L('内容・日付・時刻を入力してください','Enter text, date and time','Saisissez texte, date et heure'));break}if(await mutate(n=>{const i=n.plans.findIndex(x=>x.id===p.id);if(i>=0)n.plans[i]=p;else n.plans.push(p)}))closeModal();break}case 'planToggle':await mutate(n=>{const p=n.plans.find(x=>x.id===arg);p.enabled=!p.enabled});break;case 'planPlay':playPlan(S.plans.find(x=>x.id===arg));break;case 'planTrash':if(confirm(L('ごみ箱へ移しますか？','Move to trash?','Mettre à la corbeille ?')))await mutate(n=>n.plans.find(x=>x.id===arg).deleted=Date.now());break;case 'recordStart':await startRecord();break;case 'recordStop':stopRecord();break;case 'recordClear':stopRecord();recordToken++;pendingSound=null;$('recordStatus').textContent=L('文字を読み上げます','Text will be spoken','Le texte sera lu');break;case 'voiceTest':speak(L('予定のお知らせです','This is a reminder','Ceci est un rappel'));break;case 'owner':ownerEdit();break;case 'ownerSave':{const owner={...S.owner};for(const k of ['name','address','tel','hospital','hospitalTel','doctor','emergency'])owner[k]=$('o-'+k).value;const f=$('ownerPhoto').files[0];if(f)owner.photo=await imageData(f);if(await mutate(n=>n.owner=owner))closeModal();break}case 'contactSave':{const name=$('contactName').value.trim(),number=$('contactNumber').value.trim();if(number&&!/^\+?[0-9\s()\-#*]+$/.test(number)){toast(L('電話番号の形式を確認してください','Check phone number format','Vérifiez le numéro'));break}if(await mutate(n=>n.contacts[Number(arg)]={name,number}))closeModal();break}case 'dateSearch':searchFrom=arg;searchTo=arg;searchText='';nav('search');break;case 'doSearch':searchText=$('searchText').value;searchFrom=$('searchFrom').value;searchTo=$('searchTo').value;$('searchResults').innerHTML=searchResults();break;case 'clearSearch':searchText='';searchFrom='';searchTo='';render();break;case 'restore':case 'purge':{const key=arg==='entry'?'entries':arg==='med'?'medications':'plans';if(action==='purge'&&!confirm(L('完全削除します。元に戻せません。よろしいですか？','Permanently delete? This cannot be undone.','Supprimer définitivement ? Irréversible.')))break;const ok=await mutate(n=>{if(action==='purge')n[key]=n[key].filter(x=>x.id!==arg2);else delete n[key].find(x=>x.id===arg2).deleted},{undo:action!=='purge'});if(ok&&action==='purge'){undoState=null;render()}break}case 'export':await exportBackup();break;case 'importConfirm':if(window.pendingImport&&confirm(L('現在の記録を置き換えます。先にバックアップを保存しましたか？','Replace current records? Have you saved a backup first?','Remplacer les données ? Avez-vous sauvegardé avant ?'))){const imported=structuredClone(window.pendingImport);if(await mutate(n=>{Object.keys(n).forEach(k=>delete n[k]);Object.assign(n,imported)},{undo:false})){undoState=null;window.pendingImport=null;lang=S.settings.lang;planShown.clear();render();toast(t('saved'))}}break;case 'saveSettings':{const dark=$('darkSetting').checked,large=$('largeSetting').checked,hidden=['diary','vitals','women','meds','plans','calendar','quiz','games','fortune','frame','night'].filter(k=>k==='quiz'||!$('visible-'+k)?.checked);await mutate(n=>Object.assign(n.settings,{dark,large,hidden}),{undo:false});break}case 'showFrame':showPhotos(S.frames.filter(Boolean),S.frames.slice(0,Number(arg)).filter(Boolean).length);break;case 'overlayClose':closeOverlay();break;case 'framePrev':case 'frameNext':break;case 'noise':playNoise();break;case 'noiseStop':stopNoise();break;case 'quizAnswer':answerQuiz(Number(arg));break;case 'quizNext':quizIndex=(quizIndex+1)%EN_BANK.length;render();break;case 'quizHint':$('quizWords').textContent=quizState.q.english.split(' ').slice(0,Math.ceil(quizState.q.english.split(' ').length/2)).join(' ')+' …';break;case 'game':if($('modal').open)$('modal').close();startGame(Number(arg));break;case 'gameAnswer':gameAnswer(Number(arg));break;case 'cell':cellAction(arg);break;case 'drawFortune':await drawFortune();break;case 'fortuneSave':{const f=S.fortune[day()],h=hexFromLines(f.lines);await mutate(n=>n.entries.push({id:uid(),kind:'diary',when:localDT(),title:t('fortune')+' '+h.n+' '+HEX_NAMES[h.n-1],body:L(...TRIGRAMS[h.upper].idea),values:{},photos:[]}));toast(t('saved'));break}}
}catch(error){console.error(error);toast(L('操作できませんでした：','Action failed: ','Échec : ')+error.message)}});
document.addEventListener('change',e=>{if(e.target.matches('select[id^="v-"]'))$('on-'+e.target.id.slice(2)).checked=true});
document.addEventListener('submit',e=>e.preventDefault());
$('modal').addEventListener('cancel',()=>stopRecord());
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopNoise();if(overlayCleanup)closeOverlay();stopRecord();if(window.speechSynthesis)speechSynthesis.cancel()}});
window.addEventListener('beforeunload',()=>{stopNoise();stopRecord();if(overlayCleanup)overlayCleanup()});
async function boot(){try{const version=document.getElementById('appVersion');if(version)version.textContent='ver1.04';await openDB();S=await readDB()||defaults();S=normaliseState(S);lang=S.settings.lang||'ja';render();startTrafficMeter();if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});setInterval(tickPlans,1000);if(!S.lastBackup||Date.now()-new Date(S.lastBackup)>7*86400000)setTimeout(()=>toast(L('大切な記録は定期的にバックアップしてください','Back up important records regularly','Sauvegardez régulièrement vos notes importantes')),1600)}catch(e){$('app').innerHTML=`<section class="card"><h1>保存領域を開けません</h1><p>プライベートブラウズを避け、Safariで開いてください。記録の保存ができないため起動を停止しました。</p><p>Storage is unavailable. Please open in a normal Safari window.</p></section>`}}

