I.sleep=['睡眠','Sleep','Sommeil'];I.fatigue=['だるさ・生活への影響','Fatigue / daily impact','Fatigue / retentissement'];
I.traffic=['今月の推定通信量','Estimated monthly traffic','Trafic mensuel estimé'];icons.traffic='⇅';
valueOptions.sleep=[['none','よく眠れた','Slept well','Bien dormi'],['mild','少し眠りにくい','Some difficulty','Difficulté légère'],['strong','眠れず困った','Significant sleep difficulty','Difficulté importante']];
valueOptions.fatigue=[['none','なし','None','Aucune'],['mild','軽い・生活に支障なし','Mild, no daily impact','Légère, sans retentissement'],['medium','生活の一部に支障','Some daily impact','Retentissement partiel'],['strong','生活に大きな支障','Major daily impact','Retentissement important']];
const severity=[['none','なし','None','Aucun'],['mild','軽い','Mild','Léger'],['medium','中程度','Moderate','Modéré'],['strong','強い','Severe','Fort']];
