const W_NUMBERS={padCount:{max:50,step:1},urineCount:{max:50,step:1},urineVolume:{max:6000,step:50}};
const DOSE_UNITS=[['tablet','錠'],['mg','mg'],['packet','包'],['capsule','カプセル'],['mL','mL'],['g','g'],['drop','滴'],['puff','吸入'],['other','その他（備考へ）']];
function unitLabel(unit){const map={tablet:['錠','tablet(s)','comprimé(s)'],packet:['包','packet(s)','sachet(s)'],capsule:['カプセル','capsule(s)','gélule(s)'],drop:['滴','drop(s)','goutte(s)'],puff:['吸入','puff(s)','bouffée(s)'],other:['その他','other','autre']};return map[unit]?L(...map[unit]):unit}
function normaliseState(s){s.traffic=s.traffic&&typeof s.traffic==='object'&&!Array.isArray(s.traffic)?s.traffic:{startedAt:new Date().toISOString(),months:{}};if(!s.traffic.months||typeof s.traffic.months!=='object'||Array.isArray(s.traffic.months))s.traffic.months={};if(!s.traffic.startedAt)s.traffic.startedAt=new Date().toISOString();return s}
function womenFields(v){return `<p class="notice">${L('すべて任意です。回数・尿量は１日の累計。尿量は医療者の指示がある場合だけ記入してください。','All optional. Counts and volume are daily totals. Record volume only if instructed.','Tout est facultatif. Nombres et volume : totaux du jour. Volume uniquement sur consigne.')}</p>`+W.filter(w=>!S.settings.hiddenWomen?.includes(w[0])).map(w=>{const num=W_NUMBERS[w[0]];let options=w[2];if(num)options=Array.from({length:num.max/num.step+1},(_,i)=>[String(i*num.step),String(i*num.step)]);return select(L(...w[1]),'w-'+w[0],[['',L('未記入','Not recorded','Non renseigné')],...options.map(v=>[v[0],num?v[1]:L(...v.slice(1))])],v[w[0]]??'')}).join('')}
const oldValueLabel=valueLabel;valueLabel=function(k,v){return W_NUMBERS[k]?String(v):oldValueLabel(k,v)};
let vitalEnd=day(),womenMonth=day().slice(0,7),monthFit=false;
function monthRows(){return [...W,['sleep',I.sleep,valueOptions.sleep],['fatigue',I.fatigue,valueOptions.fatigue]]}
function relevantWomen(date){return active().filter(e=>e.when.slice(0,10)===date&&['women','diary'].includes(e.kind)).sort((a,b)=>a.when.localeCompare(b.when)||(a.modified||0)-(b.modified||0))}
function summaryCell(key,date){const entries=relevantWomen(date),values=entries.map(e=>e.values?.[key]).filter(v=>v!==''&&v!=null);if(!values.length)return {symbol:'',detail:L('未記録','Not recorded','Non renseigné'),grade:'blank'};
 if(W_NUMBERS[key]){const value=values[values.length-1];return {symbol:String(value),detail:L('最新の１日累計','Latest daily total','Dernier total du jour')+': '+value,grade:'numeric'}}
 const auxiliary={bleedColor:{red:['赤','R','R'],pink:['桃','P','Rse'],brown:['褐','Br','Br']},swelling:{none:['○','○','○'],left:['△左','△L','△G'],right:['△右','△R','△D'],both:['△両','△B','△2']},painSite:{abdomen:['腹','Ab','Ab'],pelvis:['骨','Pe','Ba'],back:['腰','Bk','Do'],other:['他','Et','Au']},painDuration:{brief:['短','Br','Br'],intermittent:['断','Int','Int'],continuous:['続','Con','Con']},swellingSite:{ankle:['足','An','Ch'],calf:['脛','Ca','Mo'],thigh:['腿','Th','Cu'],groin:['付','Gr','Ai'],multiple:['複','Mul','Mul']},menstruation:{none:['○','○','○'],start:['△始','△S','△D'],ongoing:['△中','△O','△C'],end:['□終','□E','□F']}};
 if(auxiliary[key]){const v=values[values.length-1];return{symbol:L(...(auxiliary[key][v]||[String(v)])),detail:valueLabel(key,v),grade:'aux'}}
 const rank=v=>({none:0,normal:0,good:0,okay:0,spot:1,light:1,mild:1,medium:2,moderate:2,strong:3,heavy:3,reduced:1,absent:2,present:1,amount:1,color:1,odor:1,difficult:1,pain:1,leak:1}[v]??1);
 const v=values.reduce((a,b)=>rank(b)>=rank(a)?b:a),r=rank(v);return {symbol:r===0?'○':r===1?'△':'□',detail:[...new Set(values.map(v=>valueLabel(key,v)))].join(' / '),grade:r===0?'good':r===1?'mild':'strong'};
}
function womenMonthView(){const [year,month]=womenMonth.split('-').map(Number),n=new Date(year,month,0).getDate(),rows=monthRows().filter(w=>!S.settings.hiddenWomen?.includes(w[0]));return title('women')+`<p>${L('縦に項目、横に日付。マスを押して、その日の記録・変更へ。','Rows are items, columns are dates. Tap a cell to view or edit a day.','Lignes : rubriques, colonnes : jours. Touchez une case pour consulter ou modifier.')}</p><section class="card"><div class="row">${btn('‹','womenPrev')}${field(L('表示月','Month','Mois'),'womenMonth',womenMonth,'month')}${btn('›','womenNext')}</div><div class="row">${btn(t('new'),'new:women','primary')}${btn(L('項目を選ぶ','Choose fields','Choisir les champs'),'womenSettings')}${btn(monthFit?L('拡大して横移動','Enlarge & scroll','Agrandir et défiler'):L('全月を見渡す','Fit full month','Voir tout le mois'),'monthFit')}</div><p class="legend"><span>○ ${L('なし・いつもどおり','None / usual','Aucun / habituel')}</span><span>△ ${L('軽い・変化あり','Mild / change','Léger / changement')}</span><span>□ ${L('中程度以上','Moderate or more','Modéré ou plus')}</span></p><small>${L('空欄＝未記録。記号は医学的な判定ではありません。同日の程度は最も強い状態、回数・尿量は最新の累計、部位・月経は最新の状態です。詳しくはマスを押してください。','Blank = not recorded. Symbols are not medical judgments. Daily severity uses the highest reported level; totals, locations and periods use the latest value. Tap for details.','Vide = non renseigné. Symboles sans jugement médical. Intensité maximale du jour ; totaux et catégories : dernière valeur. Touchez pour les détails.')}</small><div class="month-scroll ${monthFit?'fit-month':''}" style="--days:${n}"><table class="month-table"><thead><tr><th>${L('項目','Item','Rubrique')}</th>${Array.from({length:n},(_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>${rows.map(w=>`<tr><th>${esc(L(...w[1]))}</th>${Array.from({length:n},(_,i)=>{const date=womenMonth+'-'+String(i+1).padStart(2,'0'),cell=summaryCell(w[0],date);return `<td class="${cell.grade}"><button data-action="womenDay:${date}:${w[0]}" data-help="women" title="${esc(date+' '+L(...w[1])+' '+cell.detail)}" aria-label="${esc(date+' '+L(...w[1])+' '+cell.detail)}">${esc(cell.symbol)||'&nbsp;'}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">${L('「赤・桃・褐」は色、「左・右・両」は左右、「始・中・終」は月経の開始・継続・終了。数値欄は記録した数です。睡眠・だるさは日記帳で入力します。','Auxiliary letters indicate colour, side, location and period stage. Numeric fields show recorded counts. Sleep and fatigue are entered in the journal.','Les lettres indiquent couleur, côté, lieu et stade des règles. Les nombres sont ceux saisis. Sommeil et fatigue se notent dans le journal.')}</p></section>`}
function openWomenDay(date,key){const arr=relevantWomen(date);modal(`<h1>${esc(date)}</h1><h2>${esc(labelFor(key))}</h2><p>${esc(summaryCell(key,date).detail)}</p><div class="row">${btn(L('この日に記録を追加','Add record for this day','Ajouter une note ce jour'),'womenAdd:'+date+':'+key,'primary')}${btn(t('close'),'cancel')}</div>${arr.length?listEntries(arr):`<p>${t('empty')}</p>`}`)}
function shiftMonth(d){const [y,m]=womenMonth.split('-').map(Number),date=new Date(y,m-1+d,1);womenMonth=day(date).slice(0,7);render()}
function syncDial(id){const s=$(id),o=document.querySelector(`[data-dial="${id}"]`);if(!s||!o)return;o.textContent=s.value;o.setAttribute('aria-valuenow',s.value);o.setAttribute('aria-valuemin',s.options[0].value);o.setAttribute('aria-valuemax',s.options[s.options.length-1].value)}
function moveDial(id,delta){const s=$(id);if(!s)return;const i=Math.max(0,Math.min(s.options.length-1,s.selectedIndex+delta));s.selectedIndex=i;const check=$('on-'+id.slice(2));if(check)check.checked=true;syncDial(id)}

function bindDials(){document.querySelectorAll('[data-dial]').forEach(el=>{el.onwheel=e=>{if(helpMode)return;e.preventDefault();if(e.deltaY)moveDial(el.dataset.dial,e.deltaY<0?1:-1)};el.onkeydown=e=>{if(helpMode)return;if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();moveDial(el.dataset.dial,e.key==='ArrowUp'?1:-1)}};let y=null;el.onpointerdown=e=>{if(helpMode)return;e.preventDefault();e.stopPropagation();y=e.clientY;el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(y==null||helpMode)return;const steps=Math.trunc((y-e.clientY)/16);if(steps){moveDial(el.dataset.dial,steps);y-=steps*16}};el.onpointerup=el.onpointercancel=()=>y=null})}
function updateHelpButtons(){const label=helpMode?L('? 説明ON','? Help ON','? Aide ON'):L('? 説明OFF','? Help OFF','? Aide OFF');document.querySelectorAll('#helpBtn,[data-action="toggleHelp"]').forEach(b=>{b.textContent=label;b.classList.toggle('help-on',helpMode);b.setAttribute('aria-pressed',String(helpMode))});const notice=$('modalHelpNotice');if(notice)notice.innerHTML=helpMode?`<p class="notice">${L('説明モード：対象を３秒長押し。? で解除。閉じる・キャンセル・TOPはいつでも使えます。','Help mode: hold an item 3 seconds. Tap ? to exit. Close, Cancel and TOP always work.','Mode aide : appui de 3 s. ? pour quitter. Fermer, Annuler et TOP restent utilisables.')}</p>`:''}
function setHelpMode(value){helpMode=value;updateHelpButtons();$('helpBanner').hidden=!helpMode;$('helpBanner').textContent=L('説明モード：対象を３秒長押し／?で解除','Help: hold an item 3 seconds / ? to exit','Aide : appui de 3 s / ? pour quitter')}
function goTop(){if($('modal').open)closeModal();setHelpMode(false);stopNoise();nav('home')}
function officialMedicineUrl(url){try{const u=new URL(url);return u.protocol==='https:'&&(u.hostname==='pmda.go.jp'||u.hostname.endsWith('.pmda.go.jp'))&&!u.username&&!u.password}catch{return false}}
function medicineDoseFromForm(){const amount=$('medDoseNumber').value;if(amount===''){const id=$('modal').dataset.medId,m=S.medications.find(m=>m.id===id);return m?.amount==null?m?.dose||'':''}return amount+' '+unitLabel($('medUnit').value)}
function medicineLinks(m){return `<div style="margin:10px 0">${btn(L('薬効・副作用を見る（公式）','Effects & side effects (official)','Effets et effets indésirables (officiel)'),'drugInfo:'+m.id,'','meds')}</div>`}
const oldMedEdit=medEdit;medEdit=function(id){oldMedEdit(id);$('modal').dataset.medId=id;const labels={tablet:['錠','tablet(s)','comprimé(s)'],packet:['包','packet(s)','sachet(s)'],capsule:['カプセル','capsule(s)','gélule(s)'],drop:['滴','drop(s)','goutte(s)'],puff:['吸入','puff(s)','bouffée(s)'],other:['その他（備考へ）','Other (notes)','Autre (notes)']};[...$('medUnit').options].forEach(o=>{if(labels[o.value])o.textContent=L(...labels[o.value])})};
function drugInfo(id){const m=S.medications.find(m=>m.id===id);modal(`<h1>${L('薬効・副作用の確認','Medicine information','Informations du médicament')}</h1><h2>${esc(m.name)}</h2><p>${L('製品規格','Product strength','Dosage du produit')}：${esc(m.strength||t('unregistered'))}</p><p class="notice">${L('同名・規格違いを避けるため、公式サイトで正式名・規格を照合します。自動で薬効を推測しません。すべての薬に患者向けガイドがあるわけではありません。','Match the exact product name and strength on the official site. No automatically inferred effects. Not all products have patient guides.','Vérifiez nom et dosage exacts sur le site officiel. Aucun effet déduit automatiquement. Certains produits n’ont pas de guide patient.')}</p>${btn(L('薬名をコピー','Copy medicine name','Copier le nom'),'copyDrug:'+id)}<p style="margin-top:14px"><a class="official-link" href="https://www.pmda.go.jp/okusuri_search/" target="_blank" rel="noopener noreferrer">${L('PMDAおくすりサーチを開く','Open PMDA medicine search','Ouvrir la recherche PMDA')} ↗</a></p>${m.infoUrl&&officialMedicineUrl(m.infoUrl)?`<p><a class="official-link" href="${esc(m.infoUrl)}" target="_blank" rel="noopener noreferrer">${L('登録した公式薬剤情報を開く','Open saved official information','Ouvrir la fiche officielle enregistrée')} ↗</a></p>`:''}<small>${L('公式情報を検索・閲覧する通信量はWatashi Plusの計測に含まれません。','Traffic on the external information site is not included in this app’s estimate.','Le trafic du site externe n’est pas inclus dans l’estimation.')}</small><div style="margin-top:15px">${btn(t('close'),'cancel')}</div>`)}
// Resource Timing is a partial, non-billing estimate, never a carrier-data counter.
let meterSeen=new Set(),meterPending=[],meterTimer=null;
function meterRecord(entry){if(!entry||!['http:','https:'].includes(location.protocol))return;let url;try{url=new URL(entry.name,location.href)}catch{return}if(url.origin!==location.origin)return;const prefix=location.pathname.slice(0,location.pathname.lastIndexOf('/')+1);if(!url.pathname.startsWith(prefix))return;const key=[entry.entryType,entry.name,entry.startTime].join('|');if(meterSeen.has(key))return;meterSeen.add(key);const bytes=entry.transferSize;if(!Number.isFinite(bytes)||bytes<=0)return;const time=new Date(performance.timeOrigin+entry.startTime);meterPending.push({month:day(time).slice(0,7),bytes});clearTimeout(meterTimer);meterTimer=setTimeout(flushMeter,300)}
async function flushMeter(){if(!meterPending.length||!S)return;const batch=meterPending.splice(0);const ok=await mutate(n=>{n.traffic=normaliseState(n).traffic;for(const v of batch)n.traffic.months[v.month]=(Number(n.traffic.months[v.month])||0)+v.bytes},{undo:false,refresh:false});if(!ok)meterPending.unshift(...batch);if(page==='traffic'&&$('trafficValues'))$('trafficValues').innerHTML=trafficValues()}
function startTrafficMeter(){if(!S)return;mutate(()=>{},{undo:false,refresh:false});for(const e of performance.getEntriesByType('navigation'))meterRecord(e);for(const e of performance.getEntriesByType('resource'))meterRecord(e);try{const obs=new PerformanceObserver(list=>list.getEntries().forEach(meterRecord));obs.observe({type:'resource',buffered:true})}catch{}window.addEventListener('pagehide',()=>flushMeter())}
function trafficValues(){const month=day().slice(0,7),d=new Date();d.setDate(1);d.setMonth(d.getMonth()-1);const previous=day(d).slice(0,7);return [month,previous].map(m=>{const bytes=Number(S.traffic.months[m])||0;if(m<S.traffic.startedAt.slice(0,7))return `<section class="card"><h2>${esc(m)}</h2><p>${L('計測開始前：不明','Before tracking: unknown','Avant le suivi : inconnu')}</p></section>`;return `<section class="card"><h2>${esc(m)}</h2><strong style="font-size:1.8em">${(bytes/1e9).toFixed(6)} GB</strong><p>${(bytes/1e6).toFixed(3)} MB ${bytes>0&&bytes<1000?'('+bytes+' B)':''}</p></section>`}).join('')}
function trafficView(){return title('traffic')+`<div id="trafficValues">${trafficValues()}</div><section class="card"><p class="notice">${L('ブラウザーが取得できた転送サイズだけの推定です。Wi-Fiを含み、携帯回線の使用量や請求の根拠にはなりません。外部の薬剤情報サイト、ブラウザー内部の通信、取得できないサイズは含みません。','Estimate only from transfer sizes available to the browser, including Wi-Fi. Not a mobile-data or billing counter. External medicine sites, browser-internal traffic and unavailable sizes are excluded.','Estimation des tailles accessibles au navigateur, Wi-Fi inclus. Ni compteur mobile ni base de facturation. Sites externes et trafic inaccessible exclus.')}</p><p>${L('計測開始','Tracking started','Début du suivi')}：${esc(stamp(S.traffic.startedAt))}</p><p>${L('計測開始前・旧版・別ブラウザーの分は含みません。0表示は通信ゼロの保証ではありません。キャッシュ分は加算しません。','No pre-tracking, old-version or other-browser history. A zero reading does not prove zero traffic. Cached resources are not added.','Pas d’historique antérieur ni d’autre navigateur. Zéro affiché ne garantit pas zéro trafic. Cache non ajouté.')}</p>${location.protocol==='file:'?`<p>${L('現在は端末内のHTMLです。Watashi Plus本体を開く通信は発生しません。','Currently a local HTML file: opening the app itself uses no network.','Fichier HTML local : ouverture sans réseau.')}</p>`:''}</section>`}
const originalRender=render;render=function(){originalRender();if(page==='traffic')$('app').innerHTML=trafficView();if($('vitalEnd'))$('vitalEnd').onchange=e=>{if(e.target.value){vitalEnd=e.target.value;render()}};if($('womenMonth'))$('womenMonth').onchange=e=>{if(e.target.value){womenMonth=e.target.value;render()}};if(page==='home'){const cards=[...$('app').querySelectorAll('.grid')];cards[cards.length-1].insertAdjacentHTML('beforeend',tile('traffic'))}updateHelpButtons()};
const originalStorageInfo=storageInfo;storageInfo=async function(){await originalStorageInfo();const e=$('storageInfo');if(e){try{const x=await navigator.storage.estimate();e.textContent+=` / ${L('使用量GB','Used GB','Go utilisés')}：${(x.usage/1e9).toFixed(4)} GB`}catch{}}};
HELP.women=()=>[L('項目×日付の月間表です。○＝なし・通常、△＝軽い変化、□＝中程度以上。空欄は未記録。数値・色・左右・月経は補助表示です。','Monthly item-by-day table: ○ none/usual, △ mild/change, □ moderate or more. Blank means unrecorded; numbers and categories are shown separately.','Tableau mensuel : ○ aucun/habituel, △ léger/changement, □ modéré ou plus. Vide = non renseigné.'),L('マスを押してその日の詳細へ。程度は同日の最も強い状態、回数・尿量など累計は最新値です。拡大表示では横に動かせます。','Tap a cell for that day. Highest daily severity, latest cumulative totals. Enlarged view scrolls horizontally.','Touchez une case : détails du jour. Intensité maximale, derniers totaux. Vue agrandie défilante.')];
HELP.traffic=()=>[L('今月・先月の、ブラウザーで測れたWatashi Plus本体の推定転送量です。Wi-Fiを含みます。','Current and previous month’s measurable app transfer sizes, including Wi-Fi.','Tailles transférées mesurables ce mois et le précédent, Wi-Fi inclus.'),L('計測開始前・外部サイト・未取得分は含みません。携帯料金の計算には使えません。','Excludes pre-tracking, external sites and unavailable data. Not usable for billing.','Hors historique antérieur, sites externes et données inaccessibles. Pas pour facturation.')];
HELP.meds=()=>[L('薬名・製品規格・１回量の数字・単位を登録します。規格と１回量は別です。旧版の量は勝手に変換しません。','Register product name, strength, numeric dose and unit. Strength is not the dose. Legacy doses are not auto-converted.','Nom, dosage du produit, quantité par prise et unité sont distincts. Anciennes doses non converties.'),L('薬効・副作用ボタンからPMDAで正式名・規格を確認します。服用は医療者の指示に従い、アプリで量を判断しません。','Use the effects button to check exact name and strength on PMDA. Follow professional instructions; no dose decisions here.','Vérifiez nom et dosage avec PMDA. Suivez les consignes médicales, sans décision de dose ici.')];
HELP.vitals=()=>[L('日時は自由に変更できます。過去の記録は一覧の編集で開いて変更し保存。新規入力と編集は別です。','Dates can be changed. Edit existing records via Edit in the list. A new entry is separate.','Dates modifiables. Utilisez Modifier dans la liste pour une note existante.'),L('数字をホイール、指の上下、＋／−、矢印キーで変更できます。チェックした項目だけ保存します。','Change numbers by wheel, vertical drag, +/- or arrow keys. Only checked items are saved.','Modifiez par molette, glissement, +/- ou flèches. Seules les cases cochées sont enregistrées.')];
