// Additional actions are captured before the original dispatcher.
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,arg,arg2]=b.dataset.action.split(':');if(!['womenPrev','womenNext','monthFit','womenDay','womenAdd','drugInfo','copyDrug'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();if(helpMode){toast(L('３秒長押しで説明','Hold 3 seconds for help','Appui de 3 s pour aide'));return}try{if(a==='womenPrev')shiftMonth(-1);if(a==='womenNext')shiftMonth(1);if(a==='monthFit'){monthFit=!monthFit;render()}if(a==='womenDay')openWomenDay(arg,arg2);if(a==='womenAdd'){$('modal').close();newEntry(['sleep','fatigue'].includes(arg2)?'diary':'women');$('entryWhen').value=arg+'T12:00';const f=$('w-'+arg2)||$(arg2);if(f)f.scrollIntoView({block:'center'})}if(a==='drugInfo')drugInfo(arg);if(a==='copyDrug'){const name=S.medications.find(m=>m.id===arg).name;try{await navigator.clipboard.writeText(name);toast(L('薬名をコピーしました','Medicine name copied','Nom copié'))}catch{modal(`<h1>${L('薬名を選択してコピー','Select and copy the name','Sélectionnez et copiez le nom')}</h1><textarea readonly>${esc(name)}</textarea>${btn(t('close'),'cancel')}`)}}}catch(err){toast(err.message)}},true);
