document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a?.startsWith('step:'))syncDial('v-'+a.split(':')[1])});

// v0.3: week medication view, navigation, seasonal sounds, guided transfer.
I.testing=['秦さん版 1.04','Hata edition 1.04','Édition Hata 1.04'];
I.night=['音で感じる季節','Seasons in sound','Les saisons en sons'];
let settingsSeed='';function settingsFingerprint(){return JSON.stringify([...document.querySelectorAll('#app input[type=checkbox]')].map(e=>[e.id,e.checked]))}
const pageTrail=[];let restoringPage=false,modalChanged=false,modalSeed='',modalTrail=[],programmaticClose=false;
function formFingerprint(){const d=$('modal');return JSON.stringify([...d.querySelectorAll('input,select,textarea')].map(e=>[e.id,e.type==='checkbox'?e.checked:e.type==='file'?[...e.files].map(f=>f.name+f.size):e.value]))+'|'+JSON.stringify(editPhotos)+'|'+String(pendingSound)}
function dirtyModal(){return $('modal').open&&!!$('modal').querySelector('input,textarea,select')&&(modalChanged||formFingerprint()!==modalSeed)}
function mayLeave(){const dirty=dirtyModal()||(page==='settings'&&settingsSeed&&settingsSeed!==settingsFingerprint());return !dirty||confirm(L('入力した内容はまだ保存していません。保存せずに戻りますか？','You have unsaved changes. Leave without saving?','Modifications non enregistrées. Quitter sans enregistrer ?'))}
const v03Modal=modal;modal=function(html){const d=$('modal');if(d.open){modalTrail.push({nodes:[...d.childNodes],top:d.scrollTop,seed:modalSeed,changed:modalChanged,editId,photos:structuredClone(editPhotos),sound:pendingSound});d.replaceChildren()}else modalTrail=[];v03Modal(html);d.querySelector('.modal-tools').insertAdjacentHTML('afterbegin',btn('‹ '+t('back'),'pageBack'));modalChanged=false;modalSeed=formFingerprint();queueMicrotask(()=>{if(!modalChanged)modalSeed=formFingerprint()})};
const v03Close=closeModal;closeModal=function(){v03Close();modalTrail=[];modalChanged=false};
function backOne(){const help=document.querySelector('.help-page');if(help){help.remove();return}if(document.querySelector('.overlay')){closeOverlay();return}if($('modal').open){if(!mayLeave())return;const old=modalTrail.pop();if(old){stopRecord();editToken++;$('modal').replaceChildren(...old.nodes);$('modal').scrollTop=old.top;modalSeed=old.seed;modalChanged=old.changed;editId=old.editId;editPhotos=old.photos;pendingSound=old.sound;updateHelpButtons();bindDials()}else closeModal();return}if(!mayLeave())return;const previous=pageTrail.pop();if(previous){restoringPage=true;nav(previous.page);restoringPage=false;window.scrollTo(0,previous.scroll)}else nav('home')}
const v03Nav=nav;nav=function(p){if(p!==page&&!restoringPage){pageTrail.push({page,scroll:window.scrollY});if(pageTrail.length>50)pageTrail.shift()}if(p!==page)stopSeason();v03Nav(p)};
goTop=function(){if(!mayLeave())return;document.querySelectorAll('.help-page').forEach(e=>e.remove());if($('modal').open)closeModal();setHelpMode(false);stopNoise();stopSeason();nav('home')};$('homeBtn').onclick=goTop;
const v03Help=showHelp;showHelp=function(key){v03Help(key);const e=[...document.querySelectorAll('.help-page')].pop();if(e)e.querySelector('.inner').insertAdjacentHTML('afterbegin',`<div class="help-nav">${btn('TOP','goTop')}${btn('‹ '+t('back'),'pageBack')}</div>`)};
const v03Photos=showPhotos;showPhotos=function(...args){v03Photos(...args);document.querySelector('.overlay.frame .controls')?.insertAdjacentHTML('afterbegin',btn('TOP','goTop'))};
const v03Mirror=mirror;mirror=async function(){await v03Mirror();const o=document.querySelector('.overlay');if(o&&!o.querySelector('[data-action="goTop"]'))o.insertAdjacentHTML('beforeend',`<div class="mirror-nav">${btn('TOP','goTop')}${btn('‹ '+t('back'),'pageBack')}</div>`)};
['input','change'].forEach(type=>document.addEventListener(type,e=>{if(e.target.closest('#modal')&&e.target.matches('input,select,textarea'))modalChanged=true}));
$('modal').addEventListener('cancel',e=>{e.preventDefault();backOne()});
HELP.pageBack=()=>[L('直前の画面に戻ります。入力途中なら、保存せず戻る前に確認します。','Return to the previous screen. Unsaved edits require confirmation.','Retour à l’écran précédent, avec confirmation si des modifications ne sont pas enregistrées.')];
HELP.home=()=>[L('黄色のTOPボタンで表紙へ戻ります。入力途中なら保存せず戻る前に確認します。','The yellow TOP button returns home, with confirmation for unsaved edits.','Le bouton TOP jaune revient à l’accueil, avec confirmation des modifications non enregistrées.')];
// Week matrix: blank means not recorded, never automatically means missed.
let doseWeek=day(),selectedDoseId=null,weekFit=true;
function doseStatus(e){if(e.doseStatus)return e.doseStatus;return /服用済み|Taken|Pris/.test(e.body)?'taken':/見送り|Skipped|Non pris/.test(e.body)?'skipped':'unsure'}
function doseDates(){const d=new Date(doseWeek+'T12:00');return Array.from({length:7},(_,i)=>{const a=new Date(d);a.setDate(d.getDate()+i);return day(a)})}
function medicineForDose(id){return S.medications.find(m=>m.id===id)||{id,name:active().find(e=>e.medicationId===id)?.title||L('削除済みのお薬','Deleted medicine','Médicament supprimé'),times:'',deleted:true}}
function doseRows(){const dates=doseDates(),rows=[];const meds=S.medications.filter(m=>!m.deleted||active().some(e=>e.medicationId===m.id&&dates.includes(e.when.slice(0,10))));for(const e of active().filter(e=>e.kind==='dose'&&dates.includes(e.when.slice(0,10))))if(!meds.some(m=>m.id===e.medicationId))meds.push(medicineForDose(e.medicationId));for(const m of meds){const times=(m.times||'').match(/(?:[01]?\d|2[0-3]):[0-5]\d/g)||[];const slots=[...new Set(times.map(x=>x.padStart(5,'0')))];if(!slots.length)slots.push('any');for(const slot of slots)rows.push({m,slot});if(slots[0]!=='any'&&active().some(e=>e.kind==='dose'&&e.medicationId===m.id&&dates.includes(e.when.slice(0,10))&&!slots.includes(e.slot||e.when.slice(11,16))))rows.push({m,slot:'any'})}return rows}
function dosesAt(id,date,slot){const m=S.medications.find(m=>m.id===id),slots=((m?.times||'').match(/(?:[01]?\d|2[0-3]):[0-5]\d/g)||[]).map(x=>x.padStart(5,'0'));return active().filter(e=>e.kind==='dose'&&e.medicationId===id&&e.when.slice(0,10)===date&&(slot==='any'?!slots.includes(e.slot||e.when.slice(11,16)):(e.slot||e.when.slice(11,16))===slot))}
function doseMark(e){return {taken:'○',unsure:'？',skipped:'—'}[doseStatus(e)]||'？'}
function weekMeds(){const dates=doseDates();return `<section class="card"><h2>${L('１週間の服用履歴','One-week medication history','Prises sur une semaine')}</h2><div class="row">${btn('‹ '+L('前の週','Previous','Précédente'),'doseWeek:-7')}${field(L('表示開始日','Start date','Date de début'),'doseWeek',doseWeek,'date')}${btn(L('次の週','Next','Suivante')+' ›','doseWeek:7')}</div><p>${L('○ 服用済み　？ 飲んだか不明　— 見送り　空欄 未記録','○ Taken · ? Unsure · — Skipped · Blank: unrecorded','○ Pris · ? Incertain · — Non pris · Vide : non renseigné')}</p><small>${L('空欄は飲み忘れの判定ではありません。マスを押して記録・修正できます。時刻を登録すると時刻別に表示します。','Blank does not mean a missed dose. Tap a cell to record or edit. Register clock times for separate rows.','Une case vide ne signifie pas un oubli. Touchez pour noter/modifier. Les horaires créent des lignes distinctes.')}</small>${btn(weekFit?L('拡大して見る','Enlarge table','Agrandir le tableau'):L('７日を一画面で見る','Fit seven days','Afficher sept jours'),'weekFit')}<div class="week-scroll ${weekFit?'fit-week':''}"><table class="week-table"><thead><tr><th>${L('お薬・予定時刻','Medicine / time','Médicament / heure')}</th>${dates.map(d=>`<th>${d.slice(5)}<br>${new Date(d+'T12:00').toLocaleDateString(lang,{weekday:'short'})}</th>`).join('')}</tr></thead><tbody>${doseRows().map(({m,slot})=>`<tr><th>${esc(m.name)}<br><small>${slot==='any'?L('時刻指定なし・その他','Any / other time','Sans horaire / autre'):esc(slot)}</small></th>${dates.map(d=>{const arr=dosesAt(m.id,d,slot),mark=arr.map(doseMark).join(' ');return `<td class="${arr.length?'dose-'+doseStatus(arr[0]):''}">${btn(mark||'·','doseCell:'+m.id+':'+d+':'+slot,'', 'meds')}</td>`}).join('')}</tr>`).join('')||`<tr><td colspan="8">${t('empty')}</td></tr>`}</tbody></table></div></section>`}
const v03Meds=medsView;medsView=function(){const html=v03Meds(),cut=html.lastIndexOf('<h2>');return html.slice(0,cut)+weekMeds()};
function doseCell(id,date,slot){const m=medicineForDose(id),arr=dosesAt(id,date,slot);modal(`<h1>${esc(m.name)}</h1><p>${esc(date)} ${esc(slot==='any'?L('時刻指定なし・その他','Any / other time','Sans horaire / autre'):slot)}</p>${arr.map(e=>`<section class="card"><p>${esc(e.when.slice(11,16))} ${esc(e.body)}</p>${btn(t('edit'),'doseEdit:'+e.id)} ${btn(t('del'),'trash:'+e.id,'danger')}</section>`).join('')}<p class="notice">${L('飲んだか不明なとき、追加で飲むかはこのアプリで判断しないでください。','Do not use this app to decide on an extra dose if unsure.','En cas de doute, ne décidez pas ici d’une prise supplémentaire.')}</p>${btn(L('この日に服用を記録','Record for this day','Noter une prise ce jour'),'doseNew:'+id+':'+date+':'+slot,'primary')}`)}
function doseEditor(id,date,slot,entryId){const m=medicineForDose(id),e=S.entries.find(e=>e.id===entryId);selectedDoseId=entryId||null;modal(`<h1>${esc(m.name)}</h1>${field(t('date'),'doseWhen',e?.when||date+'T'+(slot==='any'?'12:00':slot),'datetime-local')}${select(L('状態','Status','État'),'doseStatus',[["taken",L('服用済み','Taken','Pris')],["unsure",L('飲んだか不明','Unsure','Incertain')],["skipped",L('見送り（記録のみ）','Skipped (record only)','Non pris (note seulement)')]],e?doseStatus(e):'taken')}${field(t('notes'),'doseNote',e?.note||'')}${modalButtons('doseSave:'+id+':'+slot)}`)}
recordDose=async function(id,status){doseEditor(id,day(),'any');$('doseStatus').value=status;modalSeed=formFingerprint()};
// Each sound is cached independently from health data, avoiding rewriting large audio on every save.
const SEASONS=[['春','Spring','Printemps'],['夏','Summer','Été'],['秋','Autumn','Automne'],['冬','Winter','Hiver']],DAYPARTS=[['朝','Morning','Matin'],['昼','Day','Jour'],['夜','Night','Nuit']];
const SOUND_DESCRIPTIONS=[['小鳥とせせらぎ','Birds & brook','Oiseaux et ruisseau'],['木立と草の風','Trees & meadow breeze','Arbres et herbes'],['草むらと遠い虫','Grass & distant insects','Herbes et insectes'],['小鳥と遠い蝉','Birds & distant cicadas','Oiseaux et cigales'],['草原と蝉','Meadow & cicadas','Prairie et cigales'],['虫の声とそよ風','Crickets & breeze','Grillons et brise'],['草の風とせせらぎ','Grass & brook','Herbes et ruisseau'],['草原を渡る風','Wind over grass','Vent dans les herbes'],['虫の声と夜風','Crickets & night wind','Grillons et vent'],['朝霧を想う風','Misty morning wind','Vent du matin brumeux'],['冬木立を想う風','Winter grove wind','Vent du bosquet'],['遠い静かな風','Distant soft wind','Vent doux lointain']];
const SOUND_COLORS=[['#eef6d9','#dcebdc','#f9f2df'],['#e0efdd','#cddfc4','#f3eddc'],['#e3e8ee','#d6dfda','#eee6ef'],['#e5f1d1','#d2e5d7','#f7f1d9'],['#d7e9d6','#c0dcb6','#e9f1cf'],['#dce6e4','#d6dfec','#e9ecd9'],['#f3ecd9','#e1e7d9','#eee4d4'],['#efe4d1','#dfdfca','#f4e9d9'],['#e5dfe6','#d9dfe6','#e9e4d6'],['#fafafa','#e1e4e6','#f0f1ef'],['#eef1ee','#dce2e5','#f7f5f0'],['#e5e8ef','#d8dce2','#edf0f3']];
const SOUND_IDS=Array.from({length:12},(_,i)=>'sound-'+String(i).padStart(2,'0'));let soundData={},soundReady=false,soundBusy=false,soundFailure='',soundSelected=0,seasonContext=null,seasonNode=null,seasonGain=null,seasonPlaying=false,stillSeason=window.matchMedia('(prefers-reduced-motion: reduce)').matches,soundController=null,seasonToken=0;
function soundLabel(i){return L(...SEASONS[Math.floor(i/3)])+' · '+L(...DAYPARTS[i%3])}
function soundRead(key){return new Promise((resolve,reject)=>{const q=db.transaction('data').objectStore('data').get('sound:'+key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
function soundWrite(key,data){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(data,'sound:'+key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const soundSafe=d=>typeof d==='string'&&d.length<2000000&&/^data:audio\/mpeg;base64,[A-Za-z0-9+/=]+$/.test(d);
function soundProgress(){return L('音源の保存','Sound storage','Sons enregistrés')+' '+Object.keys(soundData).length+' / 12'+(soundBusy?' …':'')}
function updateSoundUI(){document.querySelectorAll('[data-sound-progress]').forEach(e=>e.textContent=soundProgress());if($('soundIssue'))$('soundIssue').textContent=soundFailure;document.querySelectorAll('[data-action^="seasonPlay:"]').forEach(e=>{const i=Number(e.dataset.action.split(':')[1]);e.disabled=!soundData[SOUND_IDS[i]];e.setAttribute('aria-pressed',String(seasonPlaying&&soundSelected===i))});if($('seasonCanvas')){$('seasonCanvas').classList.toggle('moving',page==='night'&&!stillSeason&&!document.hidden);const c=SOUND_COLORS[soundSelected];c.forEach((v,i)=>$('seasonCanvas').style.setProperty('--season'+i,v));$('seasonNow').textContent=seasonPlaying?soundLabel(soundSelected)+' — '+L(...SOUND_DESCRIPTIONS[soundSelected]):L('音を選んで、ひと息。','Choose a sound and take a break.','Choisissez un son, faites une pause.')}if($('seasonCanvas'))$('seasonCanvas').classList.toggle('motion-enabled',!stillSeason);if($('seasonStill'))$('seasonStill').textContent=stillSeason?L('模様を動かす','Animate pattern','Animer le motif'):L('模様だけ止める','Pause pattern only','Figer le motif')}
async function saveSounds(){if(!S||!db||soundBusy||document.hidden)return;soundBusy=true;soundFailure='';updateSoundUI();try{if(!soundReady){for(const id of SOUND_IDS){const d=await soundRead(id);if(soundSafe(d))soundData[id]=d}soundReady=true}if(Object.keys(soundData).length===12)return;const bundle=$('soundBundle');const embedded=bundle?JSON.parse(bundle.textContent):null;for(const id of SOUND_IDS){if(soundData[id])continue;if(document.hidden)break;let data=embedded?.[id];if(!data){if(!['https:','http:'].includes(location.protocol))throw Error(L('音源付きのHTML、または公開版から開いてください。','Open the bundled HTML or hosted version.','Ouvrez le HTML complet ou la version publiée.'));soundController=new AbortController();const timeout=setTimeout(()=>soundController?.abort(),20000);try{const response=await fetch('audio/'+id+'.mp3',{signal:soundController.signal});if(!response.ok)throw Error('HTTP '+response.status);const blob=await response.blob();if(blob.size>1400000||blob.size<10000)throw Error('Audio size');data=await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(String(f.result).replace(/^data:[^;]+;/,'data:audio/mpeg;'));f.onerror=()=>reject(Error('Read'));f.readAsDataURL(blob)})}finally{clearTimeout(timeout);soundController=null}}if(!soundSafe(data))throw Error('Audio format');await soundWrite(id,data);soundData[id]=data;updateSoundUI()}}catch(e){if(!document.hidden)soundFailure=L('音源の保存が途中です。通信できるときに自動で続けます。','Sound saving paused. Resume or reopen the app.','Enregistrement interrompu. Reprenez ou rouvrez l’application.');console.warn('Sound cache paused:',e.name)}finally{soundBusy=false;updateSoundUI()}}
async function playSeason(i){if(!soundData[SOUND_IDS[i]])return;stopSeason();const token=++seasonToken;const Context=window.AudioContext||window.webkitAudioContext;seasonContext=new Context();await seasonContext.resume();const bytes=Uint8Array.from(atob(soundData[SOUND_IDS[i]].split(',')[1]),c=>c.charCodeAt(0));try{const buffer=await seasonContext.decodeAudioData(bytes.buffer);if(token!==seasonToken||page!=='night'){return}seasonNode=seasonContext.createBufferSource();seasonNode.buffer=buffer;seasonNode.loop=true;seasonGain=seasonContext.createGain();seasonGain.gain.value=Number($('seasonVolume')?.value??.45);seasonNode.connect(seasonGain).connect(seasonContext.destination);seasonNode.start();soundSelected=i;seasonPlaying=true;updateSoundUI()}catch(e){if(token===seasonToken){stopSeason();toast(L('音を再生できませんでした。音量とブラウザーをご確認ください。','Could not play sound. Check volume and browser.','Lecture impossible. Vérifiez le volume et le navigateur.'))}}}
function stopSeason(){seasonToken++;try{seasonNode?.stop()}catch{}seasonNode=null;seasonGain=null;if(seasonContext){seasonContext.close().catch(()=>{});seasonContext=null}seasonPlaying=false;updateSoundUI()}
nightView=function(){return title('night')+`<section class="card"><div id="seasonCanvas" class="season-canvas" aria-hidden="true"><div class="season-shape one"></div><div class="season-shape two"></div><div class="season-shape three"></div></div><p id="seasonNow" class="season-now"></p><div class="row">${btn(L('停止','Stop','Arrêter'),'seasonStop')}${btn('','seasonStill','','night').replace('<button','<button id="seasonStill"')}</div><label>${L('音量','Volume','Volume')}<input id="seasonVolume" type="range" min="0" max="1" step=".05" value=".45"></label><p data-sound-progress>${soundProgress()}</p><p id="soundIssue" role="status"></p><p class="notice">${L('各60秒の自然音を繰り返します。画面を離れると停止します。音はイヤホンで、小さな音量から。','Each 60-second sound loops. Stops when leaving this screen. Use headphones and start quietly.','Boucles de 60 secondes. Arrêt en quittant cet écran. Écouteurs, volume faible au départ.')}</p><div class="sound-grid">${SOUND_IDS.map((id,i)=>btn(`<strong>${soundLabel(i)}</strong><small>${L(...SOUND_DESCRIPTIONS[i])}</small>`,'seasonPlay:'+i,'sound-choice','night')).join('')}</div><details><summary>${L('音源について','About the sounds','À propos des sons')}</summary><p>${L('再配布可能な実録音を季節のイメージに合わせて編集・混合しています。日本の特定の季節・場所の実録ではありません。','Redistributable field recordings edited and mixed to evoke seasons; not recordings of specific Japanese seasons or locations.','Enregistrements réels montés et mixés pour évoquer les saisons, sans lieu ni saison japonaise spécifique.')}</p><p>BigSoundBank · CC0<br>Joseph SARDIN: 0425, 0908, 1716<br>Pierre SIBANARCO: 2716<br>Clarisse: 3002</p></details></section>`};
