const v03Backup=backupView;backupView=function(){const old=v03Backup(),storage=old.slice(old.lastIndexOf('<section class="card"><h2>'));return title('backup')+`<section class="card"><h2>${L('機種変更の準備','Prepare for a new phone','Préparer le changement de téléphone')}</h2><p class="transfer-simple">${L('① 下のボタンを押して保存してください。<br>② 保存できたことを確認してください。<br>③ 機種変更のときは、この画面をお店の方に見せてください。','1. Tap below and save.<br>2. Check that saving completed.<br>3. Show this screen to shop staff when changing phones.','1. Touchez ci-dessous et enregistrez.<br>2. Vérifiez l’enregistrement.<br>3. Montrez cet écran au magasin.')}</p>${btn(L('機種変更の準備','Prepare for a new phone','Préparer le transfert'),'export','primary')}<p>${L('最後に保存操作をした日','Last save requested','Dernière sauvegarde demandée')}：${S.lastBackup?stamp(S.lastBackup):t('unregistered')}</p><small>${L('この日付だけでは保存完了を確認できません。保存先の画面でご確認ください。','This date alone does not confirm a saved copy. Check the destination.','Cette date ne confirme pas la copie. Vérifiez la destination.')}</small><p class="notice">${L('新しいスマホで記録を確認できるまで、古いスマホのデータは消さないでください。','Keep the old phone’s data until records are checked on the new phone.','Gardez les données de l’ancien téléphone jusqu’à vérification sur le nouveau.')}</p><details><summary>${L('お店の方へ：移行の手順','For shop staff: transfer steps','Pour le magasin : transfert')}</summary><ol><li>${L('上のボタンで「watashiplus-backup-日付.json」を保存し、ダウンロード先（iPhoneでは「ファイル」など）で存在を確認してください。','Save watashiplus-backup-date.json using the button, then verify it in Downloads / Files.','Enregistrez watashiplus-backup-date.json puis vérifiez sa présence dans Téléchargements / Fichiers.')}</li><li>${L('このファイルを新端末の「ファイル」などへ移してください。保存済みの写真・記録・設定・音源が含まれます。','Transfer it to Files on the new phone. It includes saved photos, records, settings and sounds.','Transférez-le dans Fichiers sur le nouveau téléphone : photos, notes, réglages et sons enregistrés inclus.')}</li><li>${L('新端末で同じWatashi Plusを開き、下の「前のスマホの記録を取り込む」から選び、内容を確認して取り込んでください。取り込みは現在の記録を置き換えます。','Open Watashi Plus on the new phone, select the copy below, and confirm import. Import replaces existing records.','Ouvrez Watashi Plus sur le nouveau téléphone, choisissez la copie ci-dessous puis confirmez. L’import remplace les données.')}</li><li>${L('日記・写真・お薬・音源などが移ったことを確認してください。店舗によって移行対応は異なります。','Verify records, photos, medicines and sounds. Assistance varies by shop.','Vérifiez notes, photos, médicaments et sons. L’aide varie selon le magasin.')}</li></ol></details><h2>${L('前のスマホの記録を取り込む','Import from the old phone','Importer depuis l’ancien téléphone')}</h2><label>${L('保存した記録を選ぶ','Choose saved records','Choisir les données enregistrées')}<input id="importFile" type="file" accept=".json,application/json"></label><div id="importInfo"></div><small>${L('住所・病歴などを含み、暗号化されていません。移行を依頼する相手だけに渡してください。','Contains private health and contact data and is not encrypted. Share only with your chosen transfer helper.','Données privées non chiffrées : confiez-les uniquement à la personne choisie pour le transfert.')}</small></section>`+storage};
let pendingSoundPack=null;
const v03Valid=validBackup;validBackup=function(v){pendingSoundPack=null;const result=v03Valid(v);if(v.sounds!==undefined){if(!v.sounds||typeof v.sounds!=='object'||Array.isArray(v.sounds)||Object.keys(v.sounds).some(id=>!SOUND_IDS.includes(id)||!soundSafe(v.sounds[id])))throw Error('Invalid sound backup');pendingSoundPack=structuredClone(v.sounds)}return result};
exportBackup=async function(){await flushMeter();const now=new Date().toISOString(),state=structuredClone(S),sounds={};state.lastBackup=now;for(const id of SOUND_IDS){const d=await soundRead(id);if(soundSafe(d))sounds[id]=d}const blob=new Blob([JSON.stringify({format:'watashiplus-backup',version:1,exportedAt:now,state,sounds})],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='watashiplus-backup-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);await mutate(n=>n.lastBackup=now,{refresh:false});toast(L('保存を開始しました。保存先で完了を確認してください。','Saving started. Check completion at the destination.','Enregistrement lancé. Vérifiez la destination.'));if(page==='backup')render()};
async function importWithSounds(){if(!window.pendingImport)return;if(!confirm(L('現在の記録を、前のスマホの記録に置き換えます。続けますか？','Replace existing records with the imported copy?','Remplacer les données actuelles par cette copie ?')))return;const value=structuredClone(window.pendingImport),pack=pendingSoundPack;await mutationQueue;await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite'),store=tx.objectStore('data');store.put(value,'state');if(pack)for(const id of SOUND_IDS){store.delete('sound:'+id);if(pack[id])store.put(pack[id],'sound:'+id)}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});S=normaliseState(value);lang=S.settings.lang;window.pendingImport=null;pendingSoundPack=null;planShown.clear();stopSeason();if(pack){soundData=structuredClone(pack);soundReady=true}render();toast(t('saved'));saveSounds()}
const v03Render=render;render=function(){v03Render();if(!$('backBtn'))$('homeBtn').insertAdjacentHTML('afterend',`<button id="backBtn" data-action="pageBack" data-help="pageBack"></button>`);$('backBtn').textContent='‹ '+t('back');$('backBtn').disabled=pageTrail.length===0&&page==='home';if(page==='settings')settingsSeed=settingsFingerprint();if(page==='meds'&&$('doseWeek'))$('doseWeek').onchange=e=>{if(e.target.value){doseWeek=e.target.value;render()}};if(page==='night'){$('seasonVolume').oninput=e=>{if(seasonGain)seasonGain.gain.setTargetAtTime(Number(e.target.value),seasonContext.currentTime,.06)};updateSoundUI()}if(page==='home')$('app').insertAdjacentHTML('beforeend',`<p class="sound-status" data-sound-progress>${soundProgress()}</p>`);if(S&&!soundReady&&!soundBusy)setTimeout(saveSounds,0)};
