const V103_LIMITS={temp:[30,43,.1,36.5],sys:[40,300,1,120],dia:[20,220,1,80],glucose:[10,700,1,100],pulse:[20,250,1,70]};
function latestVital(k){return active().filter(e=>e.kind==='vitals'&&Number.isFinite(e.values?.[k])).sort((a,b)=>(b.modified||new Date(b.when).getTime())-(a.modified||new Date(a.when).getTime()))[0]?.values[k]}
dial=function(k,min,max,step,unit,value){const lim=V103_LIMITS[k]||[min,max,step,min];[min,max,step]=lim;const prev=latestVital(k),v=value??prev??lim[3];return `<label class="checkrow"><input class="check" type="checkbox" id="on-${k}" ${value!=null?'checked':''}><span>${t(k)} (${unit})</span></label><div class="dial">${btn('−','step:'+k+':-1')}<input id="v-${k}" aria-label="${t(k)}" type="number" min="${min}" max="${max}" step="${step}" value="${Math.min(max,Math.max(min,v))}" inputmode="decimal">${btn('＋','step:'+k+':1')}</div><small>${prev!=null?'前回保存した値：'+esc(prev)+' '+unit:'まだ記録がありません'}　入力範囲 ${min}〜${max}</small>`};
syncDial=function(){};
moveDial=function(id,delta){const el=$(id);if(!el)return;const step=Number(el.step)||1;el.value=String(Number(Math.max(Number(el.min),Math.min(Number(el.max),Number(el.value)+delta*step)).toFixed(2)));$('on-'+id.slice(2)).checked=true;el.dispatchEvent(new Event('input',{bubbles:true}))};
