let openingCamera=false;
mirror=async function(){if(openingCamera||document.querySelector('.overlay video'))return;openingCamera=true;let stream;try{if(!navigator.mediaDevices?.getUserMedia){toast('このブラウザではカメラを使えません。公開サイトをChromeやSafariで開いてください。');return}stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'user'}},audio:false});const el=document.createElement('div');el.className='overlay';el.dataset.hold='mirrorClose';el.innerHTML='<video autoplay muted playsinline></video><div class="mirror-exit">'+btn('手鏡を終了','overlayClose')+'</div>';document.body.append(el);overlayCleanup=()=>stream.getTracks().forEach(t=>t.stop());const video=el.querySelector('video');video.srcObject=stream;await video.play()}catch(e){stream?.getTracks().forEach(t=>t.stop());document.querySelector('.overlay video')?.closest('.overlay')?.remove();overlayCleanup=null;const msg={NotAllowedError:'カメラが許可されていません。ブラウザのサイト設定と、スマホ本体のアプリ権限でカメラを許可してください。',NotFoundError:'利用できるカメラが見つかりません。',NotReadableError:'カメラを使用できません。他のカメラアプリを閉じ、もう一度お試しください。',OverconstrainedError:'このカメラ設定には対応していません。'};toast(msg[e.name]||'カメラを開けませんでした。ブラウザを開き直してお試しください。');console.warn('Camera:',e.name)}finally{openingCamera=false}};
