function mealOpen(meal){batchMeal=meal;const meds=S.medications.filter(m=>!m.deleted&&(m.meals||[]).includes(meal));modal(`<h1>${MEALS.find(x=>x[0]===meal)[1]}のお薬</h1><p>${day()}　実際に飲んだ薬だけにチェックを付けてください。</p>${meds.map(m=>`<label class="meal-drug"><input type="checkbox" data-batch-med="${esc(m.id)}" ${alreadyMeal(m.id,meal)?'disabled':'checked'}><strong>${esc(m.name)}</strong><span>${esc(m.dose)}</span>${alreadyMeal(m.id,meal)?'<b>記録済み</b>':''}</label>`).join('')||'<p>登録済みのお薬がありません。薬の「編集」で朝食後などを選んで保存してください。</p>'}<p>飲まなかった薬はチェックを外してください。記録済みの取り消し・修正は、服用履歴のマスからできます。</p><div class="row">${btn('キャンセル','cancel')}${meds.length?btn('選んだ薬を飲みました','mealSave','primary'):''}</div>`);updateBatchLabel();document.querySelectorAll('[data-batch-med]').forEach(el=>el.onchange=updateBatchLabel)}
function updateBatchLabel(){const n=document.querySelectorAll('[data-batch-med]:checked:not(:disabled)').length,b=document.querySelector('[data-action="mealSave"]');if(b){b.textContent=`この${n}種類を飲みました`;b.disabled=n===0}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,id]=b.dataset.action.split(':');if(!['medSave','mealOpen','mealSave'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();if(helpMode)return;if(a==='mealOpen'){mealOpen(id);return}if(a==='medSave'){const old=S.medications.find(m=>m.id===id)||{},amount=$('medDoseNumber').value,remaining=$('medRemaining').value;if(!($('medName').value.trim())||(amount!==''&&(!Number.isFinite(+amount)||+amount<=0))||(remaining!==''&&(!Number.isFinite(+remaining)||+remaining<0))){toast('薬名・量・残量を確認してください');return}const m={...old,id:id==='new'?uid():id,name:$('medName').value.trim(),amount,unit:$('medUnit').value,dose:amount===''&&old.amount==null&&old.dose?old.dose:medicineDoseFromForm(),strength:$('medStrength').value,times:$('medTimes').value,note:$('medNote').value,remaining:remaining===''?'':+remaining,remainingUnit:$('medRemainingUnit').value,meals:MEALS.filter(([k])=>$('meal-'+k).checked).map(([k])=>k)};if(await mutate(n=>{const i=n.medications.findIndex(x=>x.id===m.id);if(i<0)n.medications.push(m);else n.medications[i]=m}))closeModal();return}if(batchSaving)return;const ids=[...document.querySelectorAll('[data-batch-med]:checked:not(:disabled)')].map(x=>x.dataset.batchMed);if(!ids.length)return;batchSaving=true;b.disabled=true;try{const meal=batchMeal,when=localDT();if(await mutate(n=>{for(const id of ids){if(n.entries.some(e=>!e.deleted&&e.medicationId===id&&e.meal===meal&&e.when.slice(0,10)===day()))continue;const m=n.medications.find(x=>x.id===id);n.entries.push({id:uid(),kind:'dose',medicationId:id,when,title:m.name,body:'服用済み',doseStatus:'taken',meal,slot:'any',photos:[],modified:Date.now()})}})){closeModal();toast(ids.length+'種類を記録しました')}}finally{batchSaving=false;if(b.isConnected)b.disabled=false}},true);
// Games: undo a board turn, and hints appropriate to the puzzle.
let gameHistory=[];
const start103=startGame;startGame=function(id){gameHistory=[];start103(id);$('modal').classList.add('colour-games');$('gameResult').insertAdjacentHTML('beforebegin',`<div class="row game-assist">${id>=24?btn('一手戻る','gameUndo'):''}${btn('ヒント','gameHint')}</div>`)};
const cell103=cellAction;cellAction=function(raw){if(gameState&&!gameState.busy&&!gameState.done){gameHistory.push(structuredClone(gameState));if(gameHistory.length>100)gameHistory.shift()}return cell103(raw)};
function gameHint103(){const g=gameState;if(!g||g.done)return;if(g.id<24){const wrong=[...document.querySelectorAll('[data-action^="gameAnswer:"]')].filter(b=>g.answers[Number(b.dataset.action.split(':')[1])]!==g.q.correct);if(wrong.length){wrong[0].disabled=true;toast('選択肢を一つ減らしました')}return}let message='';if(g.id===24){const i=g.cards.findIndex((v,i)=>!g.matched.includes(i));message='同じ絵を探しましょう。'+(i>=0?`${i+1}番は ${g.cards[i]}`:'')}if(g.id===25){for(let mask=0;mask<512;mask++){const lights=[...g.lights];for(let i=0;i<9;i++)if(mask>>i&1)for(const n of [i,i-3,i+3,i%3?i-1:-1,i%3<2?i+1:-1])if(n>=0&&n<9)lights[n]=!lights[n];if(lights.every(x=>!x)){message=mask?`${Math.log2(mask&-mask)+1}番のマスを押してみましょう。`:'全部消えています。';break}}}if(g.id===26){const queue=[[g.tiles,[]]],seen=new Set([g.tiles.join(',')]);for(let q=0;q<queue.length&&q<100000;q++){const [a,path]=queue[q];if(a.every((v,i)=>v===(i+1)%9)){message=path.length?`${g.tiles[path[0]]}のタイルを動かしてみましょう。`:'完成しています。';break}const z=a.indexOf(0);for(const n of [z-3,z+3,z%3?z-1:-1,z%3<2?z+1:-1].filter(n=>n>=0&&n<9)){const b=[...a];[b[z],b[n]]=[b[n],b[z]];const key=b.join(',');if(!seen.has(key)){seen.add(key);queue.push([b,[...path,n]])}}}message||='１・２・３を上の段に並べてみましょう。'}if(g.id===27)message=`${g.stones%4||1}個取ることを考えてみましょう。`;if(g.id===28)message=`次は「${g.next}」です。`;if(g.id===29){const queue=[[g.pos,[]]],seen=new Set([g.pos]);for(let i=0;i<queue.length;i++){const [p,path]=queue[i];if(p===24){message='次は「'+path[0]+'」です。';break}for(const [n,label] of [[p%5?p-1:-1,'左'],[p%5<4?p+1:-1,'右'],[p>=5?p-5:-1,'上'],[p<20?p+5:-1,'下']])if(n>=0&&!g.walls.includes(n)&&!seen.has(n)){seen.add(n);queue.push([n,[...path,label]])}}}toast(message)}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(!['gameHint','gameUndo'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();if(helpMode)return;if(a==='gameHint')gameHint103();else if(!gameState.busy&&gameHistory.length){gameState=gameHistory.pop();$('gameResult').textContent='一手戻しました';paintBoard()}},true);
